export enum AIModel {
  ChatGPT = 'ChatGPT',
  Gemini = 'Gemini 2.5 Flash',
  GeminiLite = 'Gemini Flash Lite',
  GeminiPro = 'Gemini 3 Pro (Thinking)',
  Claude = 'Claude',
  Other = 'Other'
}

export enum Category {
  Marketing = 'Marketing y Contenido',
  Productivity = 'Productividad y Organización',
  Creativity = 'Creatividad y Generación de Ideas',
  Analysis = 'Análisis de Data',
  Development = 'Desarrollo y Código',
  Other = 'Otros'
}

export interface PromptEntry {
  id: string;
  category: Category | string;
  name: string;
  objective: string;
  inputType: string;
  persona: string;
  recommendedAi: AIModel;
  description: string;
  content: string; // The actual prompt text
  variables: string[]; // e.g., ["Tone", "Audience"]
  usageExamples: string;
  tags: string[];
}

export type PromptFormData = Omit<PromptEntry, 'id'>;

// Interfaces para el sistema de traducción
export interface TranslationDictionary {
  app: {
    home: string;
    newPrompt: string;
    editPrompt: string;
    admin: string;
    title: string;
    searchPlaceholder: string;
    allCategories: string;
    stats: {
      total: string;
      categories: string;
      models: string;
    }
  };
  table: {
    identity: string;
    objective: string;
    engine: string;
    sourceCode: string;
    metadata: string;
    controls: string;
    emptyTitle: string;
    emptyDesc: string;
    entriesLoaded: string;
    systemReady: string;
    copy: string;
    copied: string;
    close: string;
  };
  form: {
    editTitle: string;
    newTitle: string;
    systemId: string;
    abort: string;
    save: string;
    dragDrop: {
      analyzing: string;
      analyzingSub: string;
      title: string;
      desc: string;
    };
    sections: {
      core: string;
      vars: string;
      engineering: string;
    };
    labels: {
      designation: string;
      category: string;
      engine: string;
      persona: string;
      variables: string;
      tags: string;
      objective: string;
      inputFormat: string;
      content: string;
      notes: string;
    };
    buttons: {
      audio: string;
      audioPlaying: string;
      optimize: string;
      optimizing: string;
      add: string;
    };
    placeholders: {
      name: string;
      persona: string;
      variable: string;
      tag: string;
      objective: string;
      input: string;
      content: string;
      notes: string;
    };
    status: {
      ready: string;
      varsDetected: string;
    }
  };
  admin: {
    title: string;
    subtitle: string;
    columns: {
      name: string;
      category: string;
      preview: string;
      actions: string;
    };
    buttons: {
      improveAi: string;
      edit: string;
      delete: string;
      export: string;
      import: string;
      reset: string;
    };
    empty: string;
    dataManagement: string;
  };
}

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Plus, Search, LayoutGrid, Filter, BookOpen, ChevronRight, Home, Zap, Languages, X, Megaphone, Target, Lightbulb, BarChart2, Code, Shield } from 'lucide-react';
import { PromptTable } from './components/PromptTable';
import { PromptForm } from './components/PromptModal';
import { AdminPanel } from './components/AdminPanel';
import { PromptEntry, PromptFormData, Category } from './types';
import { MOCK_PROMPTS, TRANSLATIONS } from './constants';

// Helper to get icon for category
const getCategoryIcon = (category: string) => {
  if (category === Category.Marketing) return <Megaphone size={16} className="text-pink-400" />;
  if (category === Category.Productivity) return <Target size={16} className="text-emerald-400" />;
  if (category === Category.Creativity) return <Lightbulb size={16} className="text-yellow-400" />;
  if (category === Category.Analysis) return <BarChart2 size={16} className="text-blue-400" />;
  if (category === Category.Development) return <Code size={16} className="text-cyan-400" />;
  return <LayoutGrid size={16} className="text-slate-400" />;
};

function App() {
  // Initialize state from LocalStorage or fallback to MOCK_PROMPTS
  const [prompts, setPrompts] = useState<PromptEntry[]>(() => {
    try {
      const savedData = localStorage.getItem('promptLibData');
      return savedData ? JSON.parse(savedData) : MOCK_PROMPTS;
    } catch (error) {
      console.error("Failed to load prompts from localStorage", error);
      return MOCK_PROMPTS;
    }
  });

  const [view, setView] = useState<'list' | 'form' | 'admin'>('list');
  const [editingPrompt, setEditingPrompt] = useState<PromptEntry | undefined>(undefined);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('All');

  // Refs for focus management
  const searchInputRef = useRef<HTMLInputElement>(null);
  const categorySelectRef = useRef<HTMLSelectElement>(null);

  // Language State - Default to Spanish ('es')
  const [lang, setLang] = useState<'es' | 'en'>('es');
  const t = TRANSLATIONS[lang];

  // Persistence: Save to LocalStorage whenever prompts change
  useEffect(() => {
    localStorage.setItem('promptLibData', JSON.stringify(prompts));
  }, [prompts]);

  // Filter Logic
  const filteredPrompts = useMemo(() => {
    return prompts.filter(p => {
      const matchesSearch = 
        p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.objective.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.recommendedAi.toLowerCase().includes(searchQuery.toLowerCase()) || 
        p.tags.some(t => t.toLowerCase().includes(searchQuery.toLowerCase()));

      const matchesCategory = selectedCategory === 'All' || p.category === selectedCategory;

      return matchesSearch && matchesCategory;
    });
  }, [prompts, searchQuery, selectedCategory]);

  // Actions
  const handleSave = (data: PromptFormData) => {
    if (editingPrompt) {
      setPrompts(prev => prev.map(p => p.id === editingPrompt.id ? { ...data, id: p.id } : p));
    } else {
      const newPrompt: PromptEntry = {
        ...data,
        id: Date.now().toString()
      };
      setPrompts(prev => [newPrompt, ...prev]);
    }
    setView('list');
    setEditingPrompt(undefined);
  };

  const handleDelete = (id: string) => {
    if (confirm(lang === 'es' ? '¿Estás seguro de que quieres eliminar este prompt?' : 'Are you sure you want to delete this prompt?')) {
      setPrompts(prev => prev.filter(p => p.id !== id));
    }
  };

  const handleCreate = () => {
    setEditingPrompt(undefined);
    setView('form');
  };

  const handleEdit = (prompt: PromptEntry) => {
    setEditingPrompt(prompt);
    setView('form');
  };

  const handleCancel = () => {
    setView('list');
    setEditingPrompt(undefined);
  };

  const toggleLanguage = () => {
    setLang(prev => prev === 'es' ? 'en' : 'es');
  };

  const handleAdminClick = () => {
    setView('admin');
    setEditingPrompt(undefined);
  }

  // Quick Action Handlers for Stat Buttons
  const handleTotalClick = () => {
    setSearchQuery('');
    setSelectedCategory('All');
    window.scrollTo({ top: 300, behavior: 'smooth' });
  };

  const handleCategoryClick = () => {
    categorySelectRef.current?.focus();
    categorySelectRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
  };

  const handleModelClick = () => {
    searchInputRef.current?.focus();
    searchInputRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
  };

  // Stats
  const stats = {
    total: prompts.length,
    categories: new Set(prompts.map(p => p.category)).size,
    models: new Set(prompts.map(p => p.recommendedAi)).size
  };

  return (
    <div className="min-h-screen bg-[#0B1120] font-sans text-slate-300 selection:bg-cyan-500/30 selection:text-cyan-200">

      {/* Cyberpunk Header */}
      <div className="bg-[#0f172a] border-b border-cyan-900/30 shadow-[0_4px_20px_-5px_rgba(6,182,212,0.1)] pb-24 relative overflow-hidden">

        {/* Background Glow Effects */}
        <div className="absolute top-0 right-0 w-96 h-96 bg-purple-500/10 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2 pointer-events-none"></div>
        <div className="absolute top-0 left-0 w-96 h-96 bg-cyan-500/5 rounded-full blur-3xl -translate-y-1/2 -translate-x-1/2 pointer-events-none"></div>

        <header className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 relative z-10">
          <div className="flex justify-between items-center">
            <div className="flex flex-col gap-1">
              <div className="flex items-center gap-2 text-slate-400 text-xs font-mono mb-1 tracking-wider uppercase">
                <div className="flex items-center gap-1 cursor-pointer hover:text-cyan-400 transition-colors" onClick={() => setView('list')}>
                  <Home size={12} />
                  <span>{t.app.home}</span>
                </div>
                {view === 'form' && (
                  <>
                    <ChevronRight size={12} className="text-slate-600"/>
                    <span className="text-cyan-400 animate-pulse">{editingPrompt ? t.app.editPrompt : t.app.newPrompt}</span>
                  </>
                )}
                {view === 'admin' && (
                  <>
                    <ChevronRight size={12} className="text-slate-600"/>
                    <span className="text-purple-400 animate-pulse">{t.app.admin}</span>
                  </>
                )}
              </div>
              <h1 className="text-3xl font-bold text-white tracking-tight flex items-center gap-3">
                <div className="relative">
                  <BookOpen className="text-cyan-400" size={28} />
                  <div className="absolute inset-0 bg-cyan-400 blur-md opacity-40"></div>
                </div>
                <span className="bg-clip-text text-transparent bg-gradient-to-r from-white via-slate-200 to-slate-400">
                  PromptLib <span className="text-cyan-500">Manager</span>
                </span>
              </h1>
            </div>

            <div className="flex items-center gap-4">
              {/* Admin Button */}
              <button 
                onClick={handleAdminClick}
                className="flex items-center justify-center w-8 h-8 rounded-lg border border-slate-700 bg-[#0B1120] hover:border-purple-500/50 hover:text-purple-400 text-slate-400 transition-all"
                title="Admin Console"
              >
                <Shield size={14} />
              </button>

              {/* Language Toggle */}
              <button 
                onClick={toggleLanguage}
                className="flex items-center gap-2 px-3 py-1.5 rounded-lg border border-slate-700 bg-[#0B1120] hover:border-cyan-500/50 text-xs font-mono text-slate-400 hover:text-white transition-all"
                title="Switch Language / Cambiar Idioma"
              >
                <Languages size={14} />
                <span>{lang === 'es' ? 'ES' : 'EN'}</span>
              </button>

              {view === 'list' && (
                <button 
                  onClick={handleCreate}
                  className="flex items-center gap-2 bg-cyan-500/10 hover:bg-cyan-500/20 text-cyan-300 hover:text-cyan-200 border border-cyan-500/30 px-4 py-2 rounded-lg transition-all font-semibold backdrop-blur-sm group"
                >
                  <Plus size={18} className="group-hover:rotate-90 transition-transform duration-300" />
                  <span>{t.app.newPrompt}</span>
                </button>
              )}
            </div>
          </div>
        </header>
      </div>

      {/* Main Content Area */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 -mt-16 pb-12 relative z-20">

        {view === 'list' && (
          <div className="space-y-6 animate-fadeIn">

            {/* INTERACTIVE STATS BAR (BUTTONS) */}
            <div className="bg-[#1e293b]/80 backdrop-blur-md rounded-xl shadow-xl border border-slate-700/50 p-1 flex flex-wrap items-center justify-between divide-x divide-slate-700/50">

              <button 
                onClick={handleTotalClick}
                className="flex-1 flex items-center justify-center gap-3 p-3 hover:bg-slate-800/80 active:bg-slate-800 transition-all first:rounded-l-xl group cursor-pointer active:scale-95 focus:outline-none focus:bg-slate-800"
                title="Reset filters and show all prompts"
              >
                 <div className="p-2 bg-blue-500/10 text-blue-400 rounded-lg group-hover:text-blue-300 group-hover:bg-blue-400/20 group-active:scale-90 transition-all">
                    <LayoutGrid size={20}/>
                 </div>
                 <div className="flex flex-col items-start">
                    <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest group-hover:text-blue-300 transition-colors">{t.app.stats.total}</span>
                    <span className="text-xl font-mono font-bold text-white leading-none">{stats.total}</span>
                 </div>
              </button>

              <button 
                onClick={handleCategoryClick}
                className="flex-1 flex items-center justify-center gap-3 p-3 hover:bg-slate-800/80 active:bg-slate-800 transition-all group cursor-pointer active:scale-95 focus:outline-none focus:bg-slate-800"
                title="Filter by Category"
              >
                 <div className="p-2 bg-purple-500/10 text-purple-400 rounded-lg group-hover:text-purple-300 group-hover:bg-purple-400/20 group-active:scale-90 transition-all">
                    <Filter size={20}/>
                 </div>
                 <div className="flex flex-col items-start">
                    <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest group-hover:text-purple-300 transition-colors">{t.app.stats.categories}</span>
                    <span className="text-xl font-mono font-bold text-white leading-none">{stats.categories}</span>
                 </div>
              </button>

              <button 
                onClick={handleModelClick}
                className="flex-1 flex items-center justify-center gap-3 p-3 hover:bg-slate-800/80 active:bg-slate-800 transition-all last:rounded-r-xl group cursor-pointer active:scale-95 focus:outline-none focus:bg-slate-800"
                title="Search by Model"
              >
                 <div className="p-2 bg-green-500/10 text-green-400 rounded-lg group-hover:text-green-300 group-hover:bg-green-400/20 group-active:scale-90 transition-all">
                    <Zap size={20}/>
                 </div>
                 <div className="flex flex-col items-start">
                    <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest group-hover:text-green-300 transition-colors">{t.app.stats.models}</span>
                    <span className="text-xl font-mono font-bold text-white leading-none">{stats.models}</span>
                 </div>
              </button>

            </div>

            {/* Filters & Search Bar (Dark Mode) */}
            <div className="bg-[#1e293b]/60 backdrop-blur-sm p-4 rounded-xl shadow-lg border border-slate-800 flex flex-col md:flex-row gap-4 justify-between items-center">
              <div className="relative w-full md:w-96 group">
                <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 text-slate-500 group-focus-within:text-cyan-400 transition-colors" size={20} />
                <input 
                  ref={searchInputRef}
                  type="text" 
                  placeholder={t.app.searchPlaceholder}
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full pl-12 pr-10 py-3 bg-[#0B1120] border border-slate-700 rounded-xl focus:ring-1 focus:ring-cyan-500 focus:border-cyan-500 text-slate-200 placeholder-slate-600 transition-all"
                />
                {/* Clear Search Button */}
                {searchQuery && (
                  <button 
                    onClick={() => setSearchQuery('')}
                    className="absolute right-3 top-1/2 transform -translate-y-1/2 text-slate-500 hover:text-white transition-colors bg-transparent border-none p-1"
                  >
                    <X size={16} />
                  </button>
                )}
              </div>

              <div className="flex items-center gap-3 w-full md:w-auto relative">
                {/* Visual Icon for Selected Category */}
                <div className="absolute left-4 top-1/2 -translate-y-1/2 pointer-events-none z-10">
                   {selectedCategory === 'All' ? <Filter size={20} className="text-slate-500" /> : getCategoryIcon(selectedCategory)}
                </div>

                <select 
                  ref={categorySelectRef}
                  value={selectedCategory}
                  onChange={(e) => setSelectedCategory(e.target.value)}
                  className="w-full md:w-64 py-3 pl-12 pr-4 bg-[#0B1120] border border-slate-700 rounded-xl focus:ring-1 focus:ring-cyan-500 text-slate-300 font-medium cursor-pointer hover:border-slate-600 transition-colors focus:border-purple-500 focus:ring-purple-500 appearance-none"
                >
                  <option value="All">{t.app.allCategories}</option>
                  {Object.values(Category).map(cat => (
                    <option key={cat} value={cat}>{cat}</option>
                  ))}
                </select>
                {/* Custom chevron to replace default */}
                <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-slate-500">
                  <ChevronRight size={16} className="rotate-90" />
                </div>
              </div>
            </div>

            {/* Table */}
            <PromptTable 
              prompts={filteredPrompts} 
              onEdit={handleEdit} 
              onDelete={handleDelete}
              dict={t.table}
            />
          </div>
        )}

        {view === 'form' && (
          <div className="animate-slideUp">
             <PromptForm 
                initialData={editingPrompt} 
                onSave={handleSave} 
                onCancel={handleCancel}
                dict={t.form}
             />
          </div>
        )}

        {view === 'admin' && (
           <div className="animate-slideUp">
             <AdminPanel 
               prompts={prompts} 
               setPrompts={setPrompts}
               onEdit={handleEdit}
               onDelete={handleDelete}
               dict={t.admin}
             />
           </div>
        )}

      </main>
    </div>
  );
}

export default App;

import React, { useRef } from 'react';
import { Shield, Database, Trash2, Edit2, BrainCircuit, Download, Upload, RotateCcw } from 'lucide-react';
import { PromptEntry, TranslationDictionary } from '../types';
import { MOCK_PROMPTS } from '../constants';

interface AdminPanelProps {
  prompts: PromptEntry[];
  setPrompts: React.Dispatch<React.SetStateAction<PromptEntry[]>>;
  onEdit: (prompt: PromptEntry) => void;
  onDelete: (id: string) => void;
  dict: TranslationDictionary['admin'];
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ prompts, setPrompts, onEdit, onDelete, dict }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  // 1. Export Function
  const handleExport = () => {
    const dataStr = JSON.stringify(prompts, null, 2);
    const blob = new Blob([dataStr], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `prompt_backup_${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // 2. Import Function
  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (Array.isArray(json)) {
           // Simple validation: check if items have IDs and names
           const valid = json.every(item => item.id && item.name);
           if (valid) {
             if(confirm("Esto reemplazará todos tus prompts actuales. ¿Continuar?")) {
               setPrompts(json);
               alert("Importación exitosa.");
             }
           } else {
             alert("El archivo JSON no tiene el formato correcto.");
           }
        }
      } catch (err) {
        console.error(err);
        alert("Error al leer el archivo JSON.");
      }
    };
    reader.readAsText(file);
    // Reset file input
    e.target.value = ''; 
  };

  // 3. Factory Reset
  const handleReset = () => {
    if (confirm("¿Estás seguro? Esto borrará tus datos y restaurará los ejemplos iniciales.")) {
      setPrompts(MOCK_PROMPTS);
      localStorage.removeItem('promptLibData'); // Clear storage to force reload next time or let state sync
    }
  };

  return (
    <div className="space-y-6 animate-fadeIn pb-12">

      {/* Header Panel */}
      <div className="bg-[#1e293b]/80 backdrop-blur-md rounded-2xl shadow-2xl border border-slate-700 p-8 flex flex-col md:flex-row items-center justify-between gap-4">
         <div>
            <h2 className="text-2xl font-bold text-white flex items-center gap-3">
               <Shield className="text-purple-400" size={28} />
               {dict.title}
            </h2>
            <p className="text-slate-400 mt-1 font-mono text-sm">{dict.subtitle}</p>
         </div>
         <div className="flex gap-4">
            <div className="flex items-center gap-2 px-4 py-2 bg-purple-500/10 border border-purple-500/30 rounded-lg">
               <Database size={16} className="text-purple-400" />
               <span className="text-xs font-bold text-purple-300 font-mono">{prompts.length} RECORDS</span>
            </div>
         </div>
      </div>

      {/* Data Management Section */}
      <div className="bg-[#0f172a] rounded-2xl border border-slate-700 p-6">
        <h3 className="text-lg font-bold text-slate-200 mb-4 flex items-center gap-2">
           <Database size={18} className="text-cyan-400"/>
           {dict.dataManagement}
        </h3>
        <div className="flex flex-wrap gap-4">
           {/* Export */}
           <button 
             onClick={handleExport}
             className="flex items-center gap-2 px-4 py-2.5 bg-slate-800 border border-slate-600 rounded-xl hover:bg-slate-700 text-slate-300 font-medium transition-colors"
           >
             <Download size={16} />
             {dict.buttons.export}
           </button>

           {/* Import */}
           <button 
             onClick={handleImportClick}
             className="flex items-center gap-2 px-4 py-2.5 bg-slate-800 border border-slate-600 rounded-xl hover:bg-slate-700 text-slate-300 font-medium transition-colors"
           >
             <Upload size={16} />
             {dict.buttons.import}
           </button>
           <input 
             type="file" 
             ref={fileInputRef} 
             onChange={handleFileChange} 
             accept=".json" 
             className="hidden" 
           />

           {/* Reset */}
           <button 
             onClick={handleReset}
             className="flex items-center gap-2 px-4 py-2.5 bg-red-950/20 border border-red-900/50 rounded-xl hover:bg-red-900/30 text-red-400 font-medium transition-colors ml-auto"
           >
             <RotateCcw size={16} />
             {dict.buttons.reset}
           </button>
        </div>
      </div>

      {/* Database Table */}
      <div className="bg-[#0f172a] rounded-2xl border border-slate-700 shadow-xl overflow-hidden">
         {prompts.length === 0 ? (
            <div className="p-12 text-center text-slate-500">
               <Database size={48} className="mx-auto mb-4 opacity-30" />
               <p>{dict.empty}</p>
            </div>
         ) : (
            <table className="w-full">
               <thead>
                  <tr className="bg-[#1e293b] border-b border-slate-700 text-left">
                     <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">{dict.columns.name}</th>
                     <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">{dict.columns.category}</th>
                     <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider w-1/3">{dict.columns.preview}</th>
                     <th className="px-6 py-4 text-right text-xs font-bold text-slate-400 uppercase tracking-wider">{dict.columns.actions}</th>
                  </tr>
               </thead>
               <tbody className="divide-y divide-slate-800">
                  {prompts.map(prompt => (
                     <tr key={prompt.id} className="hover:bg-slate-800/50 transition-colors">
                        <td className="px-6 py-4">
                           <div className="font-bold text-slate-200">{prompt.name}</div>
                           <div className="text-xs text-slate-500 font-mono mt-0.5">{prompt.id}</div>
                        </td>
                        <td className="px-6 py-4">
                           <span className="inline-block px-2 py-1 bg-slate-800 rounded text-xs text-cyan-400 border border-slate-700">
                              {prompt.category.split(' ')[0]}...
                           </span>
                        </td>
                        <td className="px-6 py-4">
                           <div className="text-sm text-slate-400 truncate max-w-xs font-mono opacity-70">
                              {prompt.content.substring(0, 60)}...
                           </div>
                        </td>
                        <td className="px-6 py-4 text-right">
                           <div className="flex justify-end gap-3">
                              {/* Primary Action: IMPROVE WITH AI */}
                              <button 
                                 onClick={() => onEdit(prompt)}
                                 className="flex items-center gap-2 px-3 py-1.5 bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-500 hover:to-indigo-500 text-white text-xs font-bold rounded-lg shadow-lg shadow-purple-900/30 transition-all transform hover:scale-105"
                                 title="Open Editor to Optimize"
                              >
                                 <BrainCircuit size={14} />
                                 {dict.buttons.improveAi}
                              </button>

                              <button 
                                 onClick={() => onEdit(prompt)}
                                 className="p-1.5 text-slate-400 hover:text-white hover:bg-slate-700 rounded-lg transition-colors"
                                 title={dict.buttons.edit}
                              >
                                 <Edit2 size={16} />
                              </button>

                              <button 
                                 onClick={() => onDelete(prompt.id)}
                                 className="p-1.5 text-slate-500 hover:text-red-400 hover:bg-red-950/30 rounded-lg transition-colors"
                                 title={dict.buttons.delete}
                              >
                                 <Trash2 size={16} />
                              </button>
                           </div>
                        </td>
                     </tr>
                  ))}
               </tbody>
            </table>
         )}
      </div>

    </div>
  );
};

