import { PromptEntry } from '../types';
import { MOCK_PROMPTS } from '../constants';

const STORAGE_KEY = 'promptLibData';

/**
 * Servicio de Almacenamiento
 * 
 * Actualmente usa LocalStorage + Navigator Storage API para persistencia.
 * Este archivo está diseñado como una capa de abstracción.
 * Si en el futuro quieres añadir Supabase, Firebase o MongoDB,
 * solo tienes que modificar los métodos de este archivo.
 */

export const storageService = {

  // 1. Inicialización: Intenta hacer el almacenamiento "Durable" (Inborrable por el navegador)
  init: async (): Promise<boolean> => {
    if (navigator.storage && navigator.storage.persist) {
      try {
        const isPersisted = await navigator.storage.persist();
        console.log(`Persistent storage granted: ${isPersisted}`);
        return isPersisted;
      } catch (err) {
        console.warn("Could not request persistent storage", err);
        return false;
      }
    }
    return false;
  },

  // 2. Cargar Datos
  loadPrompts: (): PromptEntry[] => {
    try {
      const savedData = localStorage.getItem(STORAGE_KEY);
      if (savedData) {
        return JSON.parse(savedData);
      }
      return MOCK_PROMPTS;
    } catch (error) {
      console.error("Failed to load prompts from storage", error);
      return MOCK_PROMPTS;
    }
  },

  // 3. Guardar Datos
  savePrompts: (prompts: PromptEntry[]) => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(prompts));
      return true;
    } catch (error) {
      console.error("Failed to save prompts to storage", error);
      return false;
    }
  },

  // 4. Resetear Datos
  resetStorage: () => {
    localStorage.removeItem(STORAGE_KEY);
  },

  // Mock para futura conexión a la nube
  checkCloudConnection: async (): Promise<boolean> => {
    // Aquí iría la lógica para verificar Supabase/Firebase
    return false;
  }
};

