import { PromptEntry } from '../types';
import { MOCK_PROMPTS } from '../constants';

const DB_NAME = 'PromptLibManager';
const STORE_NAME = 'prompts';
const DB_VERSION = 1;

/**
 * Servicio de Almacenamiento Profesional usando IndexedDB
 * 
 * IndexedDB es una base de datos transaccional integrada en el navegador.
 * Permite almacenar cantidades significativas de datos estructurados.
 * Es asíncrona, por lo que no bloquea la interfaz de usuario.
 */

export const storageService = {

  // Helper privado para abrir la conexión a la base de datos
  getDB: async (): Promise<IDBDatabase> => {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);

      request.onerror = () => {
        console.error("IndexedDB error:", request.error);
        reject(request.error);
      };

      request.onsuccess = () => {
        resolve(request.result);
      };

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          // Creamos el "Store" (equivalente a una tabla) usando 'id' como clave primaria
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
    });
  },

  // 1. Inicialización: Intenta hacer el almacenamiento "Durable"
  init: async (): Promise<boolean> => {
    if (navigator.storage && navigator.storage.persist) {
      try {
        const isPersisted = await navigator.storage.persist();
        console.log(`Persistent storage granted: ${isPersisted}`);
        return isPersisted;
      } catch (err) {
        console.warn("Could not request persistent storage", err);
        return false;
      }
    }
    return false;
  },

  // 2. Cargar Datos (Asíncrono)
  loadPrompts: async (): Promise<PromptEntry[]> => {
    try {
      const db = await storageService.getDB();
      return new Promise((resolve, reject) => {
        const transaction = db.transaction(STORE_NAME, 'readonly');
        const store = transaction.objectStore(STORE_NAME);
        const request = store.getAll();

        request.onsuccess = () => {
          const results = request.result;
          // Si la base de datos está vacía (primera carga), devolvemos los MOCK_PROMPTS
          // y los guardamos para que la próxima vez existan.
          if (results.length === 0) {
             storageService.savePrompts(MOCK_PROMPTS).then(() => {
                resolve(MOCK_PROMPTS);
             });
          } else {
             resolve(results);
          }
        };

        request.onerror = () => reject(request.error);
      });
    } catch (error) {
      console.error("Failed to load prompts from IndexedDB", error);
      // Fallback seguro a MOCKs en caso de error catastrófico de DB
      return MOCK_PROMPTS;
    }
  },

  // 3. Guardar Datos (Asíncrono - Bulk Operation)
  // Esta función sobrescribe el store con el estado actual de la aplicación.
  // Es la forma más segura de mantener sincronizado el estado de React con la DB.
  savePrompts: async (prompts: PromptEntry[]): Promise<void> => {
    try {
      const db = await storageService.getDB();
      return new Promise((resolve, reject) => {
        const transaction = db.transaction(STORE_NAME, 'readwrite');
        const store = transaction.objectStore(STORE_NAME);

        // Limpiamos el store antes de guardar para asegurar que los elementos borrados en la UI desaparezcan de la DB
        store.clear();

        prompts.forEach(prompt => {
          store.put(prompt);
        });

        transaction.oncomplete = () => {
          resolve();
        };

        transaction.onerror = () => {
          console.error("Transaction error:", transaction.error);
          reject(transaction.error);
        };
      });
    } catch (error) {
      console.error("Failed to save prompts to IndexedDB", error);
    }
  },

  // 4. Resetear Datos
  resetStorage: async (): Promise<void> => {
    const db = await storageService.getDB();
    const transaction = db.transaction(STORE_NAME, 'readwrite');
    transaction.objectStore(STORE_NAME).clear();
  },

  // Mock para futura conexión a la nube
  checkCloudConnection: async (): Promise<boolean> => {
    return false;
  }
};

