// FEATURE: Analyze images (Multimodal with Vision)
export const extractPromptFromFile = async (file: File): Promise<Partial<PromptFormData>> => {
  try {
    let contentPart;
    let modelToUse = 'gemini-2.5-flash'; // Default for text/docs

    // 1. Handle Images (Use Gemini 3 Pro for advanced vision as requested)
    if (file.type.startsWith('image/')) {
      modelToUse = 'gemini-3-pro-preview';
      const base64Data = await fileToBase64(file);
      contentPart = {
        inlineData: {
          data: base64Data,
          mimeType: file.type
        }
      };
    } 
    // 2. Handle PDF
    else if (file.type === 'application/pdf') {
      const base64Data = await fileToBase64(file);
      contentPart = {
        inlineData: {
          data: base64Data,
          mimeType: file.type
        }
      };
    }
    // 3. Handle Word Documents (.docx)
    else if (file.name.endsWith('.docx') || file.type === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document') {
      const docText = await fileToDocxText(file);
      contentPart = { text: `Contenido del archivo Word:\n${docText}` };
    }
    // 4. Handle Text Files
    else {
      const textContent = await fileToText(file);
      contentPart = { text: `Contenido del archivo:\n${textContent}` };
    }

    const promptInstruction = `
      Analiza el archivo proporcionado. Parece contener un prompt, una idea para un prompt, o un documento del cual se puede extraer un prompt útil.

      Tu tarea es extraer la información y estructurarla para una biblioteca de prompts.
      1. Identifica el objetivo principal.
      2. Identifica el rol o persona sugerida.
      3. Extrae o redacta el contenido del prompt.
      4. Sugiere 3 tags relevantes.
      5. Sugiere un nombre corto para el prompt.

      Responde estrictamente en formato JSON.
    `;

    const response = await ai.models.generateContent({
      model: modelToUse,
      contents: [
        contentPart,
        { text: promptInstruction }
      ],
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            objective: { type: Type.STRING },
            persona: { type: Type.STRING },
            content: { type: Type.STRING },
            tags: { 
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ['name', 'objective', 'content', 'tags']
        }
      }
    });

    if (response.text) {
      return JSON.parse(cleanJSON(response.text));
    }
    throw new Error("No response text from Gemini");

  } catch (error) {
    console.error("Error extracting from file:", error);
    throw error;
  }
};

// FEATURE: Generate speech (TTS)
export const generateSpeechFromText = async (text: string): Promise<void> => {
  if (!text) return;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' }, // 'Puck', 'Charon', 'Kore', 'Fenrir', 'Zephyr'
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (!base64Audio) throw new Error("No audio data received");

    const outputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
    const outputNode = outputAudioContext.createGain();

    const audioBuffer = await decodeAudioData(
      decode(base64Audio),
      outputAudioContext,
      24000,
      1,
    );

    const source = outputAudioContext.createBufferSource();
    source.buffer = audioBuffer;
    source.connect(outputNode);
    outputNode.connect(outputAudioContext.destination);
    source.start();

  } catch (error) {
    console.error("Error generating speech:", error);
    throw error;
  }
};

import { PromptEntry } from '../types';
import { MOCK_PROMPTS } from '../constants';

const DB_NAME = 'PromptLibManager';
const STORE_NAME = 'prompts';
const DB_VERSION = 1;

/**
 * Servicio de Almacenamiento Profesional usando IndexedDB
 * Implementa patrón Singleton para la conexión para evitar bloqueos.
 */

let dbInstance: IDBDatabase | null = null;

export const storageService = {

  // Helper privado para abrir o reutilizar la conexión
  getDB: async (): Promise<IDBDatabase> => {
    if (dbInstance) return dbInstance;

    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);

      request.onerror = (event) => {
        console.error("IndexedDB connection error:", request.error);
        reject(request.error);
      };

      request.onsuccess = (event) => {
        dbInstance = request.result;

        // Manejar cierre inesperado (ej. otra pestaña actualiza versión)
        dbInstance.onversionchange = () => {
          dbInstance?.close();
          dbInstance = null;
          console.warn("Database connection closed due to version change");
        };

        dbInstance.onclose = () => {
          dbInstance = null;
        };

        resolve(dbInstance);
      };

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
    });
  },

  // 1. Inicialización
  init: async (): Promise<boolean> => {
    if (navigator.storage && navigator.storage.persist) {
      try {
        const isPersisted = await navigator.storage.persist();
        console.log(`Persistent storage granted: ${isPersisted}`);
        return isPersisted;
      } catch (err) {
        console.warn("Could not request persistent storage", err);
        return false;
      }
    }
    return false;
  },

  // 2. Cargar Datos
  loadPrompts: async (): Promise<PromptEntry[]> => {
    try {
      const db = await storageService.getDB();
      return new Promise((resolve, reject) => {
        const transaction = db.transaction(STORE_NAME, 'readonly');
        const store = transaction.objectStore(STORE_NAME);
        const request = store.getAll();

        request.onsuccess = () => {
          const results = request.result;
          // Si es la primera vez (vacío), cargamos mocks
          if (!results || results.length === 0) {
             // IMPORTANTE: No guardamos automáticamente aquí para evitar condiciones de carrera.
             // Simplemente devolvemos los mocks y dejamos que el App decida cuándo guardar.
             console.log("Database empty, returning mocks.");
             resolve(MOCK_PROMPTS);
          } else {
             console.log(`Loaded ${results.length} prompts from DB.`);
             resolve(results);
          }
        };

        request.onerror = () => {
          console.error("Error reading from store:", request.error);
          reject(request.error);
        };
      });
    } catch (error) {
      console.error("Critical failure in loadPrompts:", error);
      throw error; // Re-throw para que App.tsx sepa que falló
    }
  },

  // 3. Guardar Datos (Transacción Segura)
  savePrompts: async (prompts: PromptEntry[]): Promise<void> => {
    try {
      const db = await storageService.getDB();
      return new Promise((resolve, reject) => {
        const transaction = db.transaction(STORE_NAME, 'readwrite');
        const store = transaction.objectStore(STORE_NAME);

        // Método drástico pero seguro para sincronización exacta: Clear + Put All
        // SOLO si la transacción anterior fue exitosa.
        const clearRequest = store.clear();

        clearRequest.onsuccess = () => {
           prompts.forEach(prompt => {
             store.put(prompt);
           });
        };

        transaction.oncomplete = () => {
          resolve();
        };

        transaction.onerror = (event) => {
          console.error("Transaction error during save:", transaction.error);
          reject(transaction.error);
        };
      });
    } catch (error) {
      console.error("Failed to save prompts to IndexedDB", error);
      throw error;
    }
  },

  // 4. Resetear
  resetStorage: async (): Promise<void> => {
    const db = await storageService.getDB();
    const transaction = db.transaction(STORE_NAME, 'readwrite');
    transaction.objectStore(STORE_NAME).clear();
  },

  checkCloudConnection: async (): Promise<boolean> => {
    return false;
  }
};

