  // Create a map of active categories for the Kanban view
  const categorizedPrompts = categories.reduce((acc, cat) => {
    const matching = prompts.filter(p => p.category === cat);
    if (matching.length > 0) acc[cat] = matching;
    return acc;
  }, {} as Record<string, PromptEntry[]>);

  return (
    <div className="flex overflow-x-auto gap-6 pb-6 animate-slideUp snap-x snap-mandatory min-h-[600px] items-start">
      {Object.keys(categorizedPrompts).length > 0 ? (
         categories.map(cat => {
            const items = categorizedPrompts[cat];
            if (!items) return null;
            const config = getCategoryConfig(cat);
            const Icon = config.icon;

            return (
              <div key={cat} className="min-w-[340px] max-w-[340px] flex flex-col gap-4 snap-center">
                 {/* Column Header */}
                 <div className={`flex items-center justify-between p-3 rounded-xl bg-slate-900/80 border border-slate-800 backdrop-blur-sm sticky top-0 z-20 shadow-lg ${config.border}`}>
                    <div className="flex items-center gap-3">
                       <div className={`p-2 rounded-lg ${config.bg}`}>
                          <Icon size={18} className={config.color} />
                       </div>
                       <div className="flex flex-col">
                          <span className="text-sm font-bold text-slate-200 leading-tight">
                             {cat.split(' ')[0]}
                          </span>
                          <span className="text-[10px] text-slate-500 uppercase tracking-wider line-clamp-1">
                             {cat.split(' ').slice(1).join(' ')}
                          </span>
                       </div>
                    </div>
                    <span className="bg-[#1e293b] text-slate-400 text-xs font-mono font-bold px-2.5 py-1 rounded-lg border border-slate-700">
                       {items.length}
