        <p className="text-[10px] font-mono text-slate-300 leading-relaxed line-clamp-3 opacity-90">
          "{prompt.content}"
        </p>
      </div>

      {/* Footer Actions */}
      <div className="grid grid-cols-2 gap-2 mt-auto relative z-10 pt-1">
        <button 
          onClick={() => onEdit(prompt)}
          className="flex items-center justify-center gap-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 hover:border-slate-600 text-slate-200 font-bold py-2 px-3 rounded-lg transition-all text-xs uppercase tracking-wide"
        >
          <Rocket size={14} />
          <span>{dict.openAction.split('/')[0]}</span>
        </button>

        <button 
          onClick={handleCopy}
          className={`flex items-center justify-center gap-2 border font-bold py-2 px-3 rounded-lg transition-all text-xs uppercase tracking-wide ${isCopied ? 'bg-green-500/10 border-green-500/50 text-green-400' : 'bg-slate-800 hover:bg-slate-700 border-slate-700 text-slate-300'}`}
        >
          {isCopied ? <Check size={14} /> : <Copy size={14} />}
          <span>{isCopied ? dict.copied : dict.copy}</span>
        </button>
      </div>
    </div>
  );
};

export const PromptTable: React.FC<PromptTableProps> = ({ prompts, onEdit, onDelete, dict }) => {
  if (prompts.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-24 bg-[#1e293b]/20 rounded-xl border-2 border-dashed border-slate-800 text-center animate-fadeIn">
        <div className="bg-slate-800/50 p-4 rounded-full mb-4 border border-slate-700">
          <Sparkles className="h-10 w-10 text-slate-500" />
        </div>
        <h3 className="text-xl font-bold text-slate-200 font-mono">{dict.emptyTitle}</h3>
        <p className="text-slate-500 mt-2 max-w-sm text-sm">{dict.emptyDesc}</p>
      </div>
    );
  }

  const categories = Object.values(Category);

  // Agrupar prompts por categoría
  const categorizedPrompts = categories.reduce((acc, cat) => {
    const matching = prompts.filter(p => p.category === cat);
    acc[cat] = matching;
    return acc;
  }, {} as Record<string, PromptEntry[]>);

  // Filtrar categorías que tienen items
  const displayCategories = categories.filter(cat => categorizedPrompts[cat]?.length > 0);

  return (
    /* 
      USO DE COLUMNS-1 (Mobile) y COLUMNS-2 (Tablet/Desktop)
      Esto crea un layout tipo "Masonry" donde las categorías se organizan
      en dos columnas verticales fluyendo naturalmente.
    */
    <div className="columns-1 md:columns-2 gap-6 space-y-6 pb-12 animate-slideUp">
      {displayCategories.length > 0 ? (
        displayCategories.map(cat => {
           const items = categorizedPrompts[cat] || [];
           const config = getCategoryConfig(cat);
           const Icon = config.icon;

           return (
             <div key={cat} className="break-inside-avoid mb-6 bg-[#131b2d] rounded-3xl border border-slate-800/60 p-6 shadow-xl shadow-black/20 hover:border-slate-700 transition-colors">
                {/* Section Header */}
                <div className={`flex items-center gap-3 border-b border-slate-800 pb-4 mb-4 ${config.color}`}>
                   <div className={`p-2.5 rounded-xl ${config.bg} ${config.shadow} shadow-lg`}>
                      <Icon size={24} />
                   </div>
                   <h3 className="text-xl font-bold text-slate-200 tracking-tight">{cat}</h3>
                   <span className="text-xs font-mono font-bold text-slate-500 bg-[#1e293b] px-3 py-1 rounded-full border border-slate-700 ml-auto">
                      {items.length}
                   </span>
                </div>

                {/* Grid dentro de la categoría: siempre 1 columna porque la categoría ya ocupa el 50% de la pantalla */}
                <div className="grid grid-cols-1 gap-4">
                   {items.map(prompt => (
                      <PromptCard 
                         key={prompt.id} 
                         prompt={prompt} 
                         onEdit={onEdit} 
                         onDelete={onDelete} 
                         dict={dict} 
                      />
                   ))}
                </div>
             </div>
           );
        })
      ) : (
        <div className="w-full text-center py-20 text-slate-500 border-2 border-dashed border-slate-800 rounded-xl col-span-full">
           <LayoutGrid className="mx-auto mb-2 opacity-50" />
           No matching prompts found.
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Loader2, Plus, Upload, BrainCircuit, Save, X, Lightbulb, Volume2, Cpu, Edit2 } from 'lucide-react';
import { PromptEntry, PromptFormData, Category, AIModel, TranslationDictionary } from '../types';
import { optimizePromptContent, generateTags, extractPromptFromFile, generateSpeechFromText } from '../services/geminiService';

interface PromptFormProps {
  onCancel: () => void;
  onSave: (data: PromptFormData) => void;
  initialData?: PromptEntry;
  dict: TranslationDictionary['form'];
}

const INITIAL_DATA: PromptFormData = {
  category: Category.Marketing,
  name: '',
  objective: '',
  inputType: 'Texto',
  persona: '',
  recommendedAi: AIModel.ChatGPT,
  description: '',
  content: '',
  variables: [],
  usageExamples: '',
  tags: []
};

export const PromptForm: React.FC<PromptFormProps> = ({ onCancel, onSave, initialData, dict }) => {
  const [formData, setFormData] = useState<PromptFormData>(INITIAL_DATA);
  const [isOptimizing, setIsOptimizing] = useState(false);
  const [isExtracting, setIsExtracting] = useState(false);
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);
  const [newVariable, setNewVariable] = useState('');
  const [newTag, setNewTag] = useState('');
  const [dragActive, setDragActive] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (initialData) {
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      const { id, ...rest } = initialData;
      setFormData(rest);
    } else {
      setFormData(INITIAL_DATA);
    }
  }, [initialData]);

  // Helper to extract variables from text
  const extractVariablesFromText = (text: string): string[] => {
    const regex = /\[(.*?)\]/g;
    const matches = [...text.matchAll(regex)].map(m => m[1]);
    // Return unique variables
    return [...new Set(matches)];
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;

    if (name === 'content') {
      // Auto-detect variables when content changes
      const detectedVariables = extractVariablesFromText(value);
      setFormData(prev => ({ 
        ...prev, 
        [name]: value,
        variables: detectedVariables 
      }));
    } else {
      setFormData(prev => ({ ...prev, [name]: value }));
    }
  };

  const handleOptimize = async () => {
    if (!formData.objective) {
      alert("Por favor define un objetivo primero para que la IA pueda ayudarte.");
      return;
    }
    setIsOptimizing(true);
    try {
      const optimizedContent = await optimizePromptContent(formData);
      const autoTags = await generateTags(formData.objective, formData.category);
      const detectedVariables = extractVariablesFromText(optimizedContent);

      setFormData(prev => ({
        ...prev,
        content: optimizedContent,
        variables: detectedVariables,
        tags: [...new Set([...prev.tags, ...autoTags])]
      }));
    } catch (error) {
      console.error(error);
      alert("Error conectando con Gemini. Verifica tu API Key.");
    } finally {
      setIsOptimizing(false);
    }
  };

  const handleSpeak = async () => {
    if (!formData.content) return;
    setIsPlayingAudio(true);
    try {
      await generateSpeechFromText(formData.content);
      setTimeout(() => setIsPlayingAudio(false), 5000); 
    } catch (error) {
      console.error("TTS Error", error);
      setIsPlayingAudio(false);
    }
  };

  const processFile = async (file: File) => {
    setIsExtracting(true);
    try {
      const extractedData = await extractPromptFromFile(file);
      const newContent = extractedData.content || formData.content;
      const detectedVariables = extractVariablesFromText(newContent);

      setFormData(prev => ({
        ...prev,
        name: extractedData.name || prev.name,
        objective: extractedData.objective || prev.objective,
        persona: extractedData.persona || prev.persona,
        content: newContent,
        variables: detectedVariables,
        tags: extractedData.tags ? [...new Set([...prev.tags, ...extractedData.tags])] : prev.tags,
        description: `Importado de ${file.name}`
      }));
    } catch (error) {
      console.error("Error extracting file:", error);
      alert("No se pudo extraer información del archivo.");
    } finally {
      setIsExtracting(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) processFile(file);
  };

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  const addVariable = () => {
    if (newVariable.trim()) {
      setFormData(prev => ({ ...prev, variables: [...prev.variables, newVariable.trim()] }));
      setNewVariable('');
    }
  };

  const removeVariable = (index: number) => {
    setFormData(prev => ({ ...prev, variables: prev.variables.filter((_, i) => i !== index) }));
  };

  const addTag = () => {
    if (newTag.trim()) {
      setFormData(prev => ({ ...prev, tags: [...prev.tags, newTag.trim()] }));
      setNewTag('');
    }
  };

  const removeTag = (index: number) => {
    setFormData(prev => ({ ...prev, tags: prev.tags.filter((_, i) => i !== index) }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(formData);
  };

  const inputClass = "w-full border border-slate-700 rounded-xl p-3 focus:ring-1 focus:ring-cyan-500 focus:border-cyan-500 bg-[#0f172a] text-slate-200 placeholder-slate-600 transition-all";
  const labelClass = "block text-xs font-bold text-cyan-500/80 uppercase tracking-wider mb-2";

  return (
    <div className="bg-[#1e293b]/80 backdrop-blur-md rounded-2xl shadow-2xl border border-slate-700 overflow-hidden">

      {/* Form Header */}
      <div className="px-8 py-6 border-b border-slate-700 bg-[#0f172a]/50 flex justify-between items-center">
        <div>
           <h2 className="text-2xl font-bold text-white flex items-center gap-2">
              {initialData ? <Edit2 size={24} className="text-cyan-400"/> : <Cpu size={24} className="text-cyan-400"/>}
              {initialData ? dict.editTitle : dict.newTitle}
            </h2>
            <p className="text-slate-500 mt-1 text-sm font-mono">{dict.systemId}: {initialData?.id || 'NEW_ENTRY'}</p>
        </div>
        <div className="flex gap-3">
           <button 
            type="button" 
            onClick={onCancel}
            className="px-5 py-2.5 text-slate-400 bg-transparent border border-slate-600 rounded-xl hover:bg-white/5 hover:text-white font-medium transition-colors"
          >
            {dict.abort}
          </button>
          <button 
            onClick={handleSubmit}
            className="flex items-center gap-2 px-6 py-2.5 text-white bg-cyan-600 rounded-xl hover:bg-cyan-500 font-medium shadow-lg shadow-cyan-900/50 transition-all"
          >
            <Save size={18} />
            {dict.save}
          </button>
        </div>
      </div>

      {/* Body */}
      <form onSubmit={handleSubmit} className="p-8 space-y-8">

        {/* File Upload Section */}
        {!initialData && (
          <div 
            className={`border-2 border-dashed rounded-2xl p-10 text-center transition-all duration-300 ${dragActive ? 'bg-cyan-950/30 border-cyan-400 scale-[1.01]' : 'bg-[#0f172a] border-slate-700 hover:border-cyan-500/50 hover:bg-[#0f172a]/80'}`}
            onDragEnter={handleDrag}
            onDragLeave={handleDrag}
            onDragOver={handleDrag}
            onDrop={handleDrop}
          >
            <input 
              type="file" 
              ref={fileInputRef}
              onChange={handleFileUpload}
              className="hidden" 
              accept=".pdf,.jpg,.jpeg,.png,.txt,.md,.markdown,.doc,.docx"
            />
            <div className="flex flex-col items-center justify-center gap-4 cursor-pointer" onClick={() => fileInputRef.current?.click()}>
              {isExtracting ? (
                 <div className="flex flex-col items-center text-cyan-400 py-2">
                   <Loader2 className="animate-spin mb-4" size={48} />
                   <span className="font-bold text-xl font-mono">{dict.dragDrop.analyzing}</span>
                   <span className="text-sm text-cyan-600 mt-2">{dict.dragDrop.analyzingSub}</span>
                 </div>
              ) : (
                <>
                  <div className="bg-slate-800 p-5 rounded-2xl shadow-md text-cyan-500 ring-1 ring-slate-700 mb-2 transform transition-transform hover:scale-110">
                    <Upload size={36} />
                  </div>
                  <div>
                    <h3 className="text-lg font-bold text-slate-200">{dict.dragDrop.title}</h3>
                    <p className="text-slate-500 mt-1 max-w-md mx-auto text-sm">{dict.dragDrop.desc}</p>
                  </div>
                </>
              )}
            </div>
          </div>
        )}

        {/* Main Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">

          {/* Left Column: Context & Meta */}
          <div className="lg:col-span-4 space-y-8">
             <div className="space-y-5">
                <div className="flex items-center gap-2 mb-2 text-cyan-400">
                   <span className="font-mono font-bold text-sm">[01]</span>
                   <h3 className="font-bold text-slate-200 text-lg">{dict.sections.core}</h3>
                </div>

                <div className="bg-[#0f172a]/50 p-6 rounded-2xl border border-slate-700 space-y-5">
                  <div>
                    <label className={labelClass}>{dict.labels.designation}</label>
                    <input 
                      type="text" 
                      name="name" 
                      required
                      value={formData.name} 
                      onChange={handleChange}
                      className={inputClass}
                      placeholder={dict.placeholders.name}
                    />
                  </div>

                  <div>
                    <label className={labelClass}>{dict.labels.category}</label>
                    <div className="relative">
                      <select 
                        name="category" 
                        value={formData.category} 
                        onChange={handleChange}
                        className={`${inputClass} appearance-none cursor-pointer`}
                      >
                        {Object.values(Category).map(cat => (
                          <option key={cat} value={cat}>{cat}</option>
                        ))}
                      </select>
                    </div>
                  </div>

                  <div>
                    <label className={labelClass}>{dict.labels.engine}</label>
                     <div className="relative">
                      <select 
                        name="recommendedAi" 
                        value={formData.recommendedAi} 
                        onChange={handleChange}
                        className={`${inputClass} appearance-none cursor-pointer`}
                      >
                        {Object.values(AIModel).map(ai => (
                          <option key={ai} value={ai}>{ai}</option>
                        ))}
                      </select>
                    </div>
                  </div>

                  <div>
                    <label className={labelClass}>{dict.labels.persona}</label>
                    <input 
                      type="text" 
                      name="persona" 
                      value={formData.persona} 
                      onChange={handleChange}
                      className={inputClass}
                      placeholder={dict.placeholders.persona}
                    />
                  </div>
                </div>
             </div>

             <div className="space-y-5">
                 <div className="flex items-center gap-2 mb-2 text-purple-400">
                   <span className="font-mono font-bold text-sm">[02]</span>
                   <h3 className="font-bold text-slate-200 text-lg">{dict.sections.vars}</h3>
                </div>

                <div className="bg-[#0f172a]/50 p-6 rounded-2xl border border-slate-700 space-y-5">
                  {/* Variables */}
                  <div>
                    <div className="flex justify-between items-center mb-2">
                      <label className={labelClass}>{dict.labels.variables}</label>
                      <span className="text-[10px] text-green-400 font-mono animate-pulse">● LIVE</span>
                    </div>

                    <div className="flex gap-2 mb-3">
                      <input 
                        type="text" 
                        value={newVariable}
                        onChange={(e) => setNewVariable(e.target.value)}
                        placeholder={dict.placeholders.variable}
                        className={`${inputClass} py-2 text-sm`}
                        onKeyDown={(e) => e.key === 'Enter' && (e.preventDefault(), addVariable())}
                      />
                      <button type="button" onClick={addVariable} className="bg-slate-800 border border-slate-700 hover:bg-cyan-900/30 hover:border-cyan-700 hover:text-cyan-400 px-3 rounded-lg text-slate-400 transition-colors">
                        <Plus size={18} />
                      </button>
                    </div>

                    <div className="flex flex-wrap gap-2">
                      {formData.variables.length === 0 && <span className="text-xs text-slate-600 italic">{dict.status.varsDetected}</span>}
                      {formData.variables.map((v, idx) => (
                        <span key={idx} className="inline-flex items-center gap-1 bg-yellow-900/20 text-yellow-200 text-xs px-3 py-1.5 rounded-lg border border-yellow-900/50 font-mono">
                          {v}
                          <button type="button" onClick={() => removeVariable(idx)} className="hover:text-white ml-1"><X size={14}/></button>
                        </span>
                      ))}
                    </div>
                  </div>

                  <hr className="border-slate-700"/>

                  {/* Tags */}
                  <div>
                    <label className={labelClass}>{dict.labels.tags}</label>
                    <div className="flex gap-2 mb-3">
                      <input 
                        type="text" 
                        value={newTag}
                        onChange={(e) => setNewTag(e.target.value)}
                        placeholder={dict.placeholders.tag}
                        className={`${inputClass} py-2 text-sm`}
                        onKeyDown={(e) => e.key === 'Enter' && (e.preventDefault(), addTag())}
                      />
                      <button type="button" onClick={addTag} className="bg-slate-800 border border-slate-700 hover:bg-cyan-900/30 hover:border-cyan-700 hover:text-cyan-400 px-3 rounded-lg text-slate-400 transition-colors">
                        <Plus size={18} />
                      </button>
                    </div>
                    <div className="flex flex-wrap gap-2">
                      {formData.tags.length === 0 && <span className="text-xs text-slate-600 italic">No tags</span>}
                      {formData.tags.map((t, idx) => (
                        <span key={idx} className="inline-flex items-center gap-1 bg-slate-800 text-slate-300 text-xs px-3 py-1.5 rounded-full border border-slate-600 font-medium">
                          #{t}
                          <button type="button" onClick={() => removeTag(idx)} className="hover:text-red-400 ml-1"><X size={14}/></button>
                        </span>
                      ))}
                    </div>
                  </div>
                </div>
             </div>
          </div>

          {/* Right Column: Prompt Content */}
          <div className="lg:col-span-8 space-y-8">
             <div className="flex items-center gap-2 mb-2 text-green-400">
                <span className="font-mono font-bold text-sm">[03]</span>
                <h3 className="font-bold text-slate-200 text-lg">{dict.sections.engineering}</h3>
             </div>

            <div>
              <label className={labelClass}>{dict.labels.objective}</label>
              <input 
                type="text" 
                name="objective" 
                required
                value={formData.objective} 
                onChange={handleChange}
                placeholder={dict.placeholders.objective}
                className={`${inputClass} p-4 text-lg font-medium border-slate-600`}
              />
            </div>

            <div className="flex gap-6">
               <div className="flex-1">
                  <label className={labelClass}>{dict.labels.inputFormat}</label>
                  <input 
                    type="text" 
                    name="inputType" 
                    value={formData.inputType} 
                    onChange={handleChange}
                    placeholder={dict.placeholders.input}
                    className={inputClass}
                  />
               </div>
            </div>

            <div className="relative bg-[#0f172a] rounded-2xl p-1 border border-slate-700">
              <div className="flex justify-between items-center mb-3 px-2 pt-2">
                <label className="block text-base font-bold text-slate-200">{dict.labels.content}</label>

                <div className="flex gap-2">
                  <button
                    type="button"
                    onClick={handleSpeak}
                    disabled={isPlayingAudio || !formData.content}
                    className="flex items-center gap-2 text-xs font-mono font-bold bg-slate-800 border border-slate-600 text-slate-300 px-3 py-2 rounded-lg hover:bg-slate-700 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {isPlayingAudio ? <Loader2 className="animate-spin text-cyan-400" size={14} /> : <Volume2 size={14} />}
                    {isPlayingAudio ? dict.buttons.audioPlaying : dict.buttons.audio}
                  </button>

                  <button 
                    type="button"
                    onClick={handleOptimize}
                    disabled={isOptimizing || isExtracting}
                    className="flex items-center gap-2 text-xs font-mono font-bold bg-gradient-to-r from-purple-600 to-indigo-600 text-white px-4 py-2 rounded-lg hover:shadow-lg hover:from-purple-500 hover:to-indigo-500 transition-all disabled:opacity-50 disabled:cursor-not-allowed border border-white/10"
                  >
                    {isOptimizing ? <Loader2 className="animate-spin" size={14} /> : <BrainCircuit size={14} />}
                    {isOptimizing ? dict.buttons.optimizing : dict.buttons.optimize}
                  </button>
                </div>
              </div>

              <div className="relative group">
                <textarea 
                  name="content" 
                  rows={16}
                  required
                  value={formData.content} 
                  onChange={handleChange}
                  placeholder={dict.placeholders.content}
                  className="w-full bg-[#0B1120] border-y border-slate-800 p-6 font-mono text-sm leading-relaxed focus:ring-0 focus:border-cyan-500/50 text-cyan-50 placeholder-slate-700 transition-colors resize-y"
                />
              </div>
              <div className="p-2 bg-[#0f172a] rounded-b-xl flex justify-between items-center">
                 <p className="text-[10px] text-slate-500 flex items-center gap-1 font-mono">
                   <div className="w-1.5 h-1.5 bg-green-500 rounded-full"></div>
                   {dict.status.ready}
                 </p>
                 <p className="text-[10px] text-slate-500 flex items-center gap-1">
                    <Lightbulb size={10} className="text-yellow-500"/>
                    <span>{dict.status.varsDetected}</span>
                 </p>
              </div>
            </div>

            <div>
              <label className={labelClass}>{dict.labels.notes}</label>
              <textarea 
                name="description" 
                rows={3}
                value={formData.description} 
                onChange={handleChange}
                placeholder={dict.placeholders.notes}
                className={inputClass}
              />
            </div>
          </div>
        </div>
      </form>
    </div>
  );
};

import React, { useState } from 'react';
import { Edit2, Copy, Check, Terminal, Megaphone, Target, Lightbulb, BarChart2, Code, LayoutGrid, Sparkles, Rocket } from 'lucide-react';
import { PromptEntry, Category, TranslationDictionary } from '../types';

interface PromptTableProps {
  prompts: PromptEntry[];
  onEdit: (prompt: PromptEntry) => void;
  // onDelete removed as it is not used in the Card view
  dict: TranslationDictionary['table'];
}

// Helper to get visual config for category
const getCategoryConfig = (category: string) => {
  switch (category) {
    case Category.Marketing: 
      return { icon: Megaphone, color: 'text-orange-400', bg: 'bg-orange-500/10', border: 'border-orange-500/20', shadow: 'shadow-orange-500/20' };
    case Category.Productivity: 
      return { icon: Target, color: 'text-emerald-400', bg: 'bg-emerald-500/10', border: 'border-emerald-500/20', shadow: 'shadow-emerald-500/20' };
    case Category.Creativity: 
      return { icon: Lightbulb, color: 'text-yellow-400', bg: 'bg-yellow-500/10', border: 'border-yellow-500/20', shadow: 'shadow-yellow-500/20' };
    case Category.Analysis: 
      return { icon: BarChart2, color: 'text-blue-400', bg: 'bg-blue-500/10', border: 'border-blue-500/20', shadow: 'shadow-blue-500/20' };
    case Category.Development: 
      return { icon: Code, color: 'text-purple-400', bg: 'bg-purple-500/10', border: 'border-purple-500/20', shadow: 'shadow-purple-500/20' };
    default: 
      return { icon: LayoutGrid, color: 'text-slate-400', bg: 'bg-slate-500/10', border: 'border-slate-500/20', shadow: 'shadow-slate-500/20' };
  }
};

interface PromptCardProps {
  prompt: PromptEntry;
  onEdit: (p: PromptEntry) => void;
  dict: TranslationDictionary['table'];
}

const PromptCard: React.FC<PromptCardProps> = ({ 
  prompt, 
  onEdit, 
  dict 
}) => {
  const [isCopied, setIsCopied] = useState(false);
  const config = getCategoryConfig(prompt.category as string);

  const handleCopy = (e: React.MouseEvent) => {
    e.stopPropagation();
    navigator.clipboard.writeText(prompt.content);
    setIsCopied(true);
    setTimeout(() => setIsCopied(false), 2000);
  };

  return (
    <div className="group relative bg-[#1e293b] rounded-2xl border border-slate-700 p-5 flex flex-col gap-4 hover:border-cyan-500/50 hover:shadow-[0_0_20px_-5px_rgba(6,182,212,0.3)] hover:-translate-y-1 transition-all duration-300 w-full">

      {/* Background decoration */}
      <div className={`absolute top-0 right-0 w-24 h-24 ${config.bg} rounded-bl-full opacity-20 -mr-5 -mt-5 transition-opacity group-hover:opacity-30 pointer-events-none`}></div>

      {/* Header: Name & Edit */}
      <div className="flex justify-between items-start relative z-10">
         <div className="flex flex-col gap-1 pr-6">
            <h3 className="text-lg font-bold text-white leading-tight group-hover:text-cyan-400 transition-colors">
                {prompt.name}
            </h3>
         </div>
         <button 
           onClick={() => onEdit(prompt)}
           className="absolute top-0 right-0 text-slate-500 hover:text-cyan-400 p-1 transition-colors opacity-0 group-hover:opacity-100"
         >
           <Edit2 size={16} />
         </button>
      </div>

      {/* Objective */}
      <p className="text-sm text-slate-400 leading-relaxed relative z-10 line-clamp-2">
         {prompt.objective}
      </p>

      {/* Prompt Preview Box */}
      <div className="relative z-10 bg-[#0B1120] rounded-xl p-3 border border-slate-800 group-hover:border-slate-600 transition-colors">
        <div className="flex items-center gap-2 mb-1.5 text-[10px] font-bold text-cyan-500 uppercase tracking-widest">
          <Terminal size={10} />
          <span>PREVIEW</span>
        </div>
        <p className="text-[10px] font-mono text-slate-300 leading-relaxed line-clamp-3 opacity-90">
          "{prompt.content}"
        </p>
      </div>

      {/* Footer Actions */}
      <div className="grid grid-cols-2 gap-2 mt-auto relative z-10 pt-1">
        <button 
          onClick={() => onEdit(prompt)}
          className="flex items-center justify-center gap-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 hover:border-slate-600 text-slate-200 font-bold py-2 px-3 rounded-lg transition-all text-xs uppercase tracking-wide"
        >
          <Rocket size={14} />
          <span>{dict.openAction.split('/')[0]}</span>
        </button>

        <button 
          onClick={handleCopy}
          className={`flex items-center justify-center gap-2 border font-bold py-2 px-3 rounded-lg transition-all text-xs uppercase tracking-wide ${isCopied ? 'bg-green-500/10 border-green-500/50 text-green-400' : 'bg-slate-800 hover:bg-slate-700 border-slate-700 text-slate-300'}`}
        >
          {isCopied ? <Check size={14} /> : <Copy size={14} />}
          <span>{isCopied ? dict.copied : dict.copy}</span>
        </button>
      </div>
    </div>
  );
};

export const PromptTable: React.FC<PromptTableProps> = ({ prompts, onEdit, dict }) => {
  if (prompts.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-24 bg-[#1e293b]/20 rounded-xl border-2 border-dashed border-slate-800 text-center animate-fadeIn">
        <div className="bg-slate-800/50 p-4 rounded-full mb-4 border border-slate-700">
          <Sparkles className="h-10 w-10 text-slate-500" />
        </div>
        <h3 className="text-xl font-bold text-slate-200 font-mono">{dict.emptyTitle}</h3>
        <p className="text-slate-500 mt-2 max-w-sm text-sm">{dict.emptyDesc}</p>
      </div>
    );
  }

  const categories = Object.values(Category);

  // Agrupar prompts por categoría
  const categorizedPrompts = categories.reduce((acc, cat) => {
    const matching = prompts.filter(p => p.category === cat);
    acc[cat] = matching;
    return acc;
  }, {} as Record<string, PromptEntry[]>);

  // Filtrar categorías que tienen items
  const displayCategories = categories.filter(cat => categorizedPrompts[cat]?.length > 0);

  return (
    /* 
      USO DE COLUMNS-1 (Mobile) y COLUMNS-2 (Tablet/Desktop)
      Esto crea un layout tipo "Masonry" donde las categorías se organizan
      en dos columnas verticales fluyendo naturalmente.
    */
    <div className="columns-1 md:columns-2 gap-6 space-y-6 pb-12 animate-slideUp">
      {displayCategories.length > 0 ? (
        displayCategories.map(cat => {
           const items = categorizedPrompts[cat] || [];
           const config = getCategoryConfig(cat);
           const Icon = config.icon;

           return (
             <div key={cat} className="break-inside-avoid mb-6 bg-[#131b2d] rounded-3xl border border-slate-800/60 p-6 shadow-xl shadow-black/20 hover:border-slate-700 transition-colors">
                {/* Section Header */}
                <div className={`flex items-center gap-3 border-b border-slate-800 pb-4 mb-4 ${config.color}`}>
                   <div className={`p-2.5 rounded-xl ${config.bg} ${config.shadow} shadow-lg`}>
                      <Icon size={24} />
                   </div>
                   <h3 className="text-xl font-bold text-slate-200 tracking-tight">{cat}</h3>
                   <span className="text-xs font-mono font-bold text-slate-500 bg-[#1e293b] px-3 py-1 rounded-full border border-slate-700 ml-auto">
                      {items.length}
                   </span>
                </div>

                {/* Grid dentro de la categoría: siempre 1 columna porque la categoría ya ocupa el 50% de la pantalla */}
                <div className="grid grid-cols-1 gap-4">
                   {items.map(prompt => (
                      <PromptCard 
                         key={prompt.id} 
                         prompt={prompt} 
                         onEdit={onEdit} 
                         dict={dict} 
                      />
                   ))}
                </div>
             </div>
           );
        })
      ) : (
        <div className="w-full text-center py-20 text-slate-500 border-2 border-dashed border-slate-800 rounded-xl col-span-full">
           <LayoutGrid className="mx-auto mb-2 opacity-50" />
           No matching prompts found.
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Plus, Search, LayoutGrid, Filter, BookOpen, ChevronRight, Home, Zap, Languages, X, Megaphone, Target, Lightbulb, BarChart2, Code, Shield, Download, UploadCloud, Database, Loader2, AlertTriangle } from 'lucide-react';
import { PromptTable } from './components/PromptTable';
import { PromptForm } from './components/PromptModal';
import { AdminPanel } from './components/AdminPanel';
import { PromptEntry, PromptFormData, Category } from './types';
import { TRANSLATIONS } from './constants';
import { storageService } from './services/storageService';

// Helper to get icon for category
const getCategoryIcon = (category: string) => {
  if (category === Category.Marketing) return <Megaphone size={16} className="text-pink-400" />;
  if (category === Category.Productivity) return <Target size={16} className="text-emerald-400" />;
  if (category === Category.Creativity) return <Lightbulb size={16} className="text-yellow-400" />;
  if (category === Category.Analysis) return <BarChart2 size={16} className="text-blue-400" />;
  if (category === Category.Development) return <Code size={16} className="text-cyan-400" />;
  return <LayoutGrid size={16} className="text-slate-400" />;
};

function App() {
  // DB Status: 'init' | 'loading' | 'ready' | 'error'
  // 'ready' is the ONLY state where autosave is allowed.
  const [dbStatus, setDbStatus] = useState<'init' | 'loading' | 'ready' | 'error'>('init');
  const [prompts, setPrompts] = useState<PromptEntry[]>([]);

  // Persistence State
  const [isPersisted, setIsPersisted] = useState(false);

  const [view, setView] = useState<'list' | 'form' | 'admin'>('list');
  const [editingPrompt, setEditingPrompt] = useState<PromptEntry | undefined>(undefined);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('All');

  // Refs for focus management
  const searchInputRef = useRef<HTMLInputElement>(null);
  const categorySelectRef = useRef<HTMLSelectElement>(null);
  const importInputRef = useRef<HTMLInputElement>(null);

  // Language State - Default to Spanish ('es')
  const [lang, setLang] = useState<'es' | 'en'>('es');
  const t = TRANSLATIONS[lang];

  // 1. INITIAL LOAD
  useEffect(() => {
    const initApp = async () => {
      setDbStatus('loading');

      // Check persistence
      const persisted = await storageService.init();
      setIsPersisted(persisted);

      // Load Data
      try {
        const loadedPrompts = await storageService.loadPrompts();
        setPrompts(loadedPrompts);
        // CRITICAL: Only set status to 'ready' if load succeeded.
        // This enables the autosave effect below.
        setDbStatus('ready'); 
      } catch (e) {
        console.error("Critical error loading DB:", e);
        // CRITICAL: Set error state. This prevents autosave from running and wiping DB with empty state.
        setDbStatus('error');
      }
    };
    initApp();
  }, []);

  // 2. AUTOSAVE EFFECT
  // Only runs when dbStatus is 'ready'. 
  // If dbStatus is 'error' or 'loading', this never runs, preserving data integrity.
  useEffect(() => {
    if (dbStatus === 'ready') {
      const saveToDb = async () => {
        try {
           await storageService.savePrompts(prompts);
        } catch (e) {
           console.error("Autosave failed:", e);
           // Optional: setDbStatus('error') if we want to stop trying, 
           // but usually we want to keep trying to save.
        }
      };

      // Debounce slightly to prevent thrashing
      const timeoutId = setTimeout(saveToDb, 500);
      return () => clearTimeout(timeoutId);
    }
  }, [prompts, dbStatus]);

  // DB Handlers (Global)
  const handleExportDB = () => {
    const dataStr = JSON.stringify(prompts, null, 2);
    const blob = new Blob([dataStr], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `promptlib_backup_${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImportClick = () => {
    importInputRef.current?.click();
  };

  const handleFileImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.name.toLowerCase().endsWith('.json')) {
      alert(lang === 'es' 
        ? "Error: El archivo seleccionado no parece ser un backup (.json)." 
        : "Error: Selected file is not a valid JSON backup.");
      e.target.value = '';
      return;
    }

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (Array.isArray(json) && json.every(item => item.id && item.name)) {
             if(confirm(lang === 'es' ? "Esto reemplazará la base de datos actual. ¿Continuar?" : "This will replace the current database. Continue?")) {
               setPrompts(json);
             }
        } else {
             alert(lang === 'es' ? "Formato de archivo inválido." : "Invalid file format.");
        }
      } catch (err) { 
        console.error("JSON Parse Error:", err);
        alert(lang === 'es' ? "Error al leer JSON." : "Error reading JSON.");
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };


  // Filter Logic
  const filteredPrompts = useMemo(() => {
    return prompts.filter(p => {
      const matchesSearch = 
        p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.objective.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.recommendedAi.toLowerCase().includes(searchQuery.toLowerCase()) || 
        p.tags.some(t => t.toLowerCase().includes(searchQuery.toLowerCase()));

      const matchesCategory = selectedCategory === 'All' || p.category === selectedCategory;

      return matchesSearch && matchesCategory;
    });
  }, [prompts, searchQuery, selectedCategory]);

  // Actions
  const handleSave = (data: PromptFormData) => {
    if (editingPrompt) {
      setPrompts(prev => prev.map(p => p.id === editingPrompt.id ? { ...data, id: p.id } : p));
    } else {
      const newPrompt: PromptEntry = {
        ...data,
        id: Date.now().toString()
      };
      setPrompts(prev => [newPrompt, ...prev]);
    }
    setView('list');
    setEditingPrompt(undefined);
  };

  const handleDelete = (id: string) => {
    if (confirm(lang === 'es' ? '¿Estás seguro de que quieres eliminar este prompt?' : 'Are you sure you want to delete this prompt?')) {
      setPrompts(prev => prev.filter(p => p.id !== id));
    }
  };

  const handleCreate = () => {
    setEditingPrompt(undefined);
    setView('form');
  };

  const handleEdit = (prompt: PromptEntry) => {
    setEditingPrompt(prompt);
    setView('form');
  };

  const handleCancel = () => {
    setView('list');
    setEditingPrompt(undefined);
  };

  const toggleLanguage = () => {
    setLang(prev => prev === 'es' ? 'en' : 'es');
  };

  const handleAdminClick = () => {
    setView('admin');
    setEditingPrompt(undefined);
  }

  // Quick Action Handlers for Stat Buttons
  const handleTotalClick = () => {
    setSearchQuery('');
    setSelectedCategory('All');
    window.scrollTo({ top: 300, behavior: 'smooth' });
  };

  const handleCategoryClick = () => {
    categorySelectRef.current?.focus();
    categorySelectRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
  };

  const handleModelClick = () => {
    searchInputRef.current?.focus();
    searchInputRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
  };

  // Stats
  const stats = {
    total: prompts.length,
    categories: new Set(prompts.map(p => p.category)).size,
    models: new Set(prompts.map(p => p.recommendedAi)).size
  };

  // ERROR STATE VIEW
  if (dbStatus === 'error') {
    return (
      <div className="min-h-screen bg-[#0B1120] flex flex-col items-center justify-center text-red-500 gap-6 p-4 text-center">
        <div className="bg-red-900/20 p-6 rounded-full border border-red-500/30 animate-pulse">
           <AlertTriangle size={64} />
        </div>
        <div>
          <h1 className="text-2xl font-bold mb-2">Error de Base de Datos</h1>
          <p className="text-slate-400 max-w-md">
            No se pudo cargar la base de datos local. Hemos detenido el guardado automático para proteger tus datos.
          </p>
        </div>
        <button 
          onClick={() => window.location.reload()}
          className="px-6 py-3 bg-red-600 text-white rounded-xl hover:bg-red-500 transition-colors font-bold"
        >
          Recargar Aplicación
        </button>
      </div>
    );
  }

  // LOADING STATE VIEW
  if (dbStatus === 'init' || dbStatus === 'loading') {
    return (
      <div className="min-h-screen bg-[#0B1120] flex flex-col items-center justify-center text-cyan-500 gap-4">
        <Loader2 size={48} className="animate-spin" />
        <span className="font-mono text-sm tracking-widest uppercase animate-pulse">Initializing IndexedDB...</span>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0B1120] font-sans text-slate-300 selection:bg-cyan-500/30 selection:text-cyan-200">

      {/* Cyberpunk Header */}
      <div className="bg-[#0f172a] border-b border-cyan-900/30 shadow-[0_4px_20px_-5px_rgba(6,182,212,0.1)] pb-24 relative overflow-hidden">

        {/* Background Glow Effects */}
        <div className="absolute top-0 right-0 w-96 h-96 bg-purple-500/10 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2 pointer-events-none"></div>
        <div className="absolute top-0 left-0 w-96 h-96 bg-cyan-500/5 rounded-full blur-3xl -translate-y-1/2 -translate-x-1/2 pointer-events-none"></div>

        <header className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 relative z-10">
          <div className="flex justify-between items-center">
            <div className="flex flex-col gap-1">
              <div className="flex items-center gap-2 text-slate-400 text-xs font-mono mb-1 tracking-wider uppercase">
                <div className="flex items-center gap-1 cursor-pointer hover:text-cyan-400 transition-colors" onClick={() => setView('list')}>
                  <Home size={12} />
                  <span>{t.app.home}</span>
                </div>
                {view === 'form' && (
                  <>
                    <ChevronRight size={12} className="text-slate-600"/>
                    <span className="text-cyan-400 animate-pulse">{editingPrompt ? t.app.editPrompt : t.app.newPrompt}</span>
                  </>
                )}
                {view === 'admin' && (
                  <>
                    <ChevronRight size={12} className="text-slate-600"/>
                    <span className="text-purple-400 animate-pulse">{t.app.admin}</span>
                  </>
                )}
              </div>
              <h1 className="text-3xl font-bold text-white tracking-tight flex items-center gap-3">
                <div className="relative">
                  <BookOpen className="text-cyan-400" size={28} />
                  <div className="absolute inset-0 bg-cyan-400 blur-md opacity-40"></div>
                </div>
                <span className="bg-clip-text text-transparent bg-gradient-to-r from-white via-slate-200 to-slate-400">
                  PromptLib <span className="text-cyan-500">Manager</span>
                </span>
              </h1>

              {/* Database Status Indicator - IMPROVED */}
              <div className="flex items-center gap-2 mt-1 px-2 py-0.5 rounded-full bg-[#1e293b] border border-slate-700 w-fit">
                 {isPersisted ? (
                   <Database size={10} className="text-emerald-400" />
                 ) : (
                   <Database size={10} className="text-blue-400" />
                 )}
                 <span className={`text-[10px] font-mono tracking-tight ${isPersisted ? 'text-emerald-400' : 'text-blue-400'}`}>
                   {t.app.db.indexed}
                 </span>
              </div>

            </div>

            <div className="flex items-center gap-3">
              {/* Permanent Database Actions */}
              <div className="hidden md:flex items-center gap-1 bg-[#1e293b] p-1 rounded-lg border border-slate-700 mr-2">
                 <button 
                   onClick={handleExportDB}
                   className="p-2 text-slate-400 hover:text-cyan-400 hover:bg-cyan-950/30 rounded-md transition-all"
                   title={t.app.backupDesc}
                 >
                   <Download size={16} />
                 </button>
                 <button 
                   onClick={handleImportClick}
                   className="p-2 text-slate-400 hover:text-purple-400 hover:bg-purple-950/30 rounded-md transition-all"
                   title={t.app.restoreDesc}
                 >
                   <UploadCloud size={16} />
                 </button>
                 <input 
                   type="file" 
                   ref={importInputRef} 
                   onChange={handleFileImport} 
                   accept=".json" 
                   className="hidden" 
                 />
              </div>

              {/* Admin Button */}
              <button 
                onClick={handleAdminClick}
                className="flex items-center justify-center w-8 h-8 rounded-lg border border-slate-700 bg-[#0B1120] hover:border-purple-500/50 hover:text-purple-400 text-slate-400 transition-all"
                title="Admin Console"
              >
                <Shield size={14} />
              </button>

              {/* Language Toggle */}
              <button 
                onClick={toggleLanguage}
                className="flex items-center gap-2 px-3 py-1.5 rounded-lg border border-slate-700 bg-[#0B1120] hover:border-cyan-500/50 text-xs font-mono text-slate-400 hover:text-white transition-all"
                title="Switch Language / Cambiar Idioma"
              >
                <Languages size={14} />
                <span>{lang === 'es' ? 'ES' : 'EN'}</span>
              </button>

              {view === 'list' && (
                <button 
                  onClick={handleCreate}
                  className="flex items-center gap-2 bg-cyan-500/10 hover:bg-cyan-500/20 text-cyan-300 hover:text-cyan-200 border border-cyan-500/30 px-4 py-2 rounded-lg transition-all font-semibold backdrop-blur-sm group ml-2"
                >
                  <Plus size={18} className="group-hover:rotate-90 transition-transform duration-300" />
                  <span>{t.app.newPrompt}</span>
                </button>
              )}
            </div>
          </div>
        </header>
      </div>

      {/* Main Content Area */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 -mt-16 pb-12 relative z-20">

        {view === 'list' && (
          <div className="space-y-6 animate-fadeIn">

            {/* INTERACTIVE STATS BAR (BUTTONS) */}
            <div className="bg-[#1e293b]/80 backdrop-blur-md rounded-xl shadow-xl border border-slate-700/50 p-1 flex flex-wrap items-center justify-between divide-x divide-slate-700/50">

              <button 
                onClick={handleTotalClick}
                className="flex-1 flex items-center justify-center gap-3 p-3 hover:bg-slate-800/80 active:bg-slate-800 transition-all first:rounded-l-xl group cursor-pointer active:scale-95 focus:outline-none focus:bg-slate-800"
                title="Reset filters and show all prompts"
              >
                 <div className="p-2 bg-blue-500/10 text-blue-400 rounded-lg group-hover:text-blue-300 group-hover:bg-blue-400/20 group-active:scale-90 transition-all">
                    <LayoutGrid size={20}/>
                 </div>
                 <div className="flex flex-col items-start">
                    <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest group-hover:text-blue-300 transition-colors">{t.app.stats.total}</span>
                    <span className="text-xl font-mono font-bold text-white leading-none">{stats.total}</span>
                 </div>
              </button>

              <button 
                onClick={handleCategoryClick}
                className="flex-1 flex items-center justify-center gap-3 p-3 hover:bg-slate-800/80 active:bg-slate-800 transition-all group cursor-pointer active:scale-95 focus:outline-none focus:bg-slate-800"
                title="Filter by Category"
              >
                 <div className="p-2 bg-purple-500/10 text-purple-400 rounded-lg group-hover:text-purple-300 group-hover:bg-purple-400/20 group-active:scale-90 transition-all">
                    <Filter size={20}/>
                 </div>
                 <div className="flex flex-col items-start">
                    <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest group-hover:text-purple-300 transition-colors">{t.app.stats.categories}</span>
                    <span className="text-xl font-mono font-bold text-white leading-none">{stats.categories}</span>
                 </div>
              </button>

              <button 
                onClick={handleModelClick}
                className="flex-1 flex items-center justify-center gap-3 p-3 hover:bg-slate-800/80 active:bg-slate-800 transition-all last:rounded-r-xl group cursor-pointer active:scale-95 focus:outline-none focus:bg-slate-800"
                title="Search by Model"
              >
                 <div className="p-2 bg-green-500/10 text-green-400 rounded-lg group-hover:text-green-300 group-hover:bg-green-400/20 group-active:scale-90 transition-all">
                    <Zap size={20}/>
                 </div>
                 <div className="flex flex-col items-start">
                    <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest group-hover:text-green-300 transition-colors">{t.app.stats.models}</span>
                    <span className="text-xl font-mono font-bold text-white leading-none">{stats.models}</span>
                 </div>
              </button>

            </div>

            {/* Filters & Search Bar (Dark Mode) */}
            <div className="bg-[#1e293b]/60 backdrop-blur-sm p-4 rounded-xl shadow-lg border border-slate-800 flex flex-col md:flex-row gap-4 justify-between items-center">
              <div className="relative w-full md:w-96 group">
