// Helper to prepare content part from file
const getFileContentPart = async (file: File): Promise<any> => {
  if (file.type.startsWith('image/') || file.type === 'application/pdf') {
     const base64Data = await fileToBase64(file);
     return {
        inlineData: {
          data: base64Data,
          mimeType: file.type
        }
      };
  } else if (file.name.endsWith('.docx') || file.type === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document') {
      const docText = await fileToDocxText(file);
      return { text: `Contenido del archivo Word:\n${docText}` };
  } else {
      const textContent = await fileToText(file);
      return { text: `Contenido del archivo:\n${textContent}` };
  }
};

// FEATURE: Extract MULTIPLE prompts from a single file (Batch Processing)
export const extractMultiplePromptsFromFile = async (file: File): Promise<Partial<PromptFormData>[]> => {
  try {
    const contentPart = await getFileContentPart(file);

    // Usamos Gemini 3 Pro porque necesitamos razonamiento fuerte para separar el texto
    const modelToUse = 'gemini-3-pro-preview'; 

    const promptInstruction = `
      ESTO ES UNA TAREA DE EXTRACCIÓN Y SEGMENTACIÓN DE DATOS.

      Analiza el documento adjunto. Contiene UNA LISTA DE MÚLTIPLES PROMPTS DIFERENTES.
      Tu trabajo es identificar dónde empieza y termina cada prompt y separarlos en objetos individuales.

      INSTRUCCIONES CRÍTICAS:
      1. Busca patrones de enumeración como "1.", "2.", "3.", "4." o títulos en negrita que indican un nuevo prompt.
      2. El documento proporcionado típicamente contiene una lista numerada (ej: 1 a 4). DEBES EXTRAER CADA UNO POR SEPARADO.
      3. NO RESUMAS el documento en un solo prompt.
      4. Si ves texto como "1. Ideas de contenido" y luego "2. Plan de contenido IG", eso son DOS prompts distintos.

      Para CADA prompt detectado, rellena la siguiente estructura:
      - name: El título del prompt (ej: "Ideas de contenido").
      - objective: El objetivo que persigue (ej: "Generar ideas para blog").
      - persona: El rol o experto mencionado (ej: "Experto en marketing").
      - content: El CUERPO COMPLETO del prompt. Copia literalmente las instrucciones que el usuario debe pegar en ChatGPT/Gemini.
      - tags: 3 palabras clave.

      Devuelve un ARRAY JSON.
    `;

    const response = await ai.models.generateContent({
      model: modelToUse,
      contents: [
        contentPart,
        { text: promptInstruction }
      ],
      config: {
        // Activamos Thinking para que el modelo "piense" cómo dividir el texto correctamente antes de generar el JSON
        thinkingConfig: {
          thinkingBudget: 16000 
        },
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              objective: { type: Type.STRING },
              persona: { type: Type.STRING },
              content: { type: Type.STRING },
              tags: { 
                type: Type.ARRAY,
                items: { type: Type.STRING }
              }
            },
            required: ['name', 'objective', 'content', 'tags']
          }
        }
      }
    });

    if (response.text) {
      const parsed = JSON.parse(cleanJSON(response.text));
      return Array.isArray(parsed) ? parsed : [parsed];
    }
    throw new Error("No response text from Gemini");

  } catch (error) {
    console.error("Error extracting batch from file:", error);
    throw error;
  }
};

