import { PromptEntry, SupabaseConfig } from '../types';
import { MOCK_PROMPTS } from '../constants';

const DB_NAME = 'PromptLibManager';
const STORE_NAME = 'prompts';
const DB_VERSION = 1;
const SUPABASE_CONFIG_KEY = 'promptlib_supabase_config';

// Declare Supabase global
declare const supabase: any;

let dbInstance: IDBDatabase | null = null;
let supabaseClient: any | null = null;

export const storageService = {

  // --- LOCAL DB (IndexedDB) ---
  getDB: async (): Promise<IDBDatabase> => {
    if (dbInstance) return dbInstance;
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);
      request.onerror = () => reject(request.error);
      request.onsuccess = () => {
        dbInstance = request.result;
        dbInstance.onversionchange = () => { dbInstance?.close(); dbInstance = null; };
        dbInstance.onclose = () => { dbInstance = null; };
        resolve(dbInstance);
      };
      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
    });
  },

  // --- SUPABASE CONFIG ---
  initSupabase: (config: SupabaseConfig) => {
    if (typeof supabase !== 'undefined') {
      try {
        supabaseClient = supabase.createClient(config.url, config.key);
        localStorage.setItem(SUPABASE_CONFIG_KEY, JSON.stringify(config));
        return true;
      } catch (e) {
        console.error("Supabase init error:", e);
        return false;
      }
    }
    return false;
  },

  disconnectSupabase: () => {
    supabaseClient = null;
    localStorage.removeItem(SUPABASE_CONFIG_KEY);
  },

  isCloudActive: () => {
    return !!supabaseClient;
  },

  // --- MAIN ACTIONS ---

  init: async (): Promise<boolean> => {
    // 1. Check for stored Supabase config
    const storedConfig = localStorage.getItem(SUPABASE_CONFIG_KEY);
    if (storedConfig) {
      try {
        const config = JSON.parse(storedConfig);
        storageService.initSupabase(config);
      } catch (e) { console.error("Invalid stored config"); }
    }

    // 2. Check Local Storage persistence
    if (navigator.storage && navigator.storage.persist) {
      try { return await navigator.storage.persist(); } 
      catch (err) { return false; }
    }
    return false;
  },

  loadPrompts: async (): Promise<PromptEntry[]> => {
    // A. TRY CLOUD FIRST
    if (supabaseClient) {
      try {
        const { data, error } = await supabaseClient.from('prompts').select('*').order('created_at', { ascending: false });
        if (!error && data) {
          return data;
        }
        console.error("Supabase fetch error:", error);
      } catch (e) {
        console.error("Supabase connection failed, falling back to local.", e);
      }
    }

    // B. FALLBACK TO LOCAL
    try {
      const db = await storageService.getDB();
      return new Promise((resolve, reject) => {
        const transaction = db.transaction(STORE_NAME, 'readonly');
        const store = transaction.objectStore(STORE_NAME);
        const request = store.getAll();
        request.onsuccess = () => {
          const results = request.result;
          resolve((!results || results.length === 0) ? MOCK_PROMPTS : results);
        };
        request.onerror = () => reject(request.error);
      });
    } catch (error) {
      throw error;
    }
  },

  savePrompts: async (prompts: PromptEntry[]): Promise<void> => {
    // ALWAYS SAVE LOCAL (Backup/Offline support)
    try {
      const db = await storageService.getDB();
      const transaction = db.transaction(STORE_NAME, 'readwrite');
      const store = transaction.objectStore(STORE_NAME);
      store.clear().onsuccess = () => {
        prompts.forEach(p => store.put(p));
      };
    } catch (e) { console.error("Local save error", e); }

    // IF CLOUD, SYNC
    if (supabaseClient) {
      try {
        // Upsert all prompts. Note: Supabase upsert requires IDs to match.
        const { error } = await supabaseClient.from('prompts').upsert(prompts);
        if (error) console.error("Supabase save error:", error);
      } catch (e) {
        console.error("Supabase crash:", e);
      }
    }
  },

  // One-time sync from Local to Cloud
  syncLocalToCloud: async (localPrompts: PromptEntry[]) => {
    if (!supabaseClient) throw new Error("No cloud connection");
    const { error } = await supabaseClient.from('prompts').upsert(localPrompts);
    if (error) throw error;
  },

  resetStorage: async (): Promise<void> => {
    const db = await storageService.getDB();
    const transaction = db.transaction(STORE_NAME, 'readwrite');
    transaction.objectStore(STORE_NAME).clear();
    if(supabaseClient) {
       // Optional: Delete from cloud too? Maybe dangerous. Let's just clear local for "Factory Reset".
       // Or delete all. Let's stick to local reset to be safe unless requested.
    }
  }
};

import React, { useState, useEffect } from 'react';
import { Cloud, CheckCircle, XCircle, Link2, UploadCloud, LogOut, Database } from 'lucide-react';
import { TranslationDictionary, PromptEntry } from '../types';
import { storageService } from '../services/storageService';

interface CloudModalProps {
  onClose: () => void;
  onConnect: () => void;
  dict: TranslationDictionary['cloud'];
  currentPrompts: PromptEntry[];
}

export const CloudModal: React.FC<CloudModalProps> = ({ onClose, onConnect, dict, currentPrompts }) => {
  const [url, setUrl] = useState('');
  const [key, setKey] = useState('');
  const [isConnected, setIsConnected] = useState(storageService.isCloudActive());
  const [isSyncing, setIsSyncing] = useState(false);

  useEffect(() => {
    const stored = localStorage.getItem('promptlib_supabase_config');
    if (stored) {
      const parsed = JSON.parse(stored);
      setUrl(parsed.url);
      setKey(parsed.key);
    }
  }, []);

  const handleConnect = () => {
    if (!url || !key) return alert("URL & Key required");
    const success = storageService.initSupabase({ url, key });
    if (success) {
      setIsConnected(true);
      onConnect(); // Refresh app state
      alert(dict.status.connected);
    } else {
      alert(dict.status.error);
    }
  };

  const handleDisconnect = () => {
    storageService.disconnectSupabase();
    setIsConnected(false);
    setUrl('');
    setKey('');
    onConnect(); // Refresh app state
  };

  const handleSync = async () => {
    if (!isConnected) return;
    setIsSyncing(true);
    try {
      await storageService.syncLocalToCloud(currentPrompts);
      alert("Sincronización completada. Tus prompts locales ahora están en Supabase.");
    } catch (e) {
      console.error(e);
      alert("Error al sincronizar.");
    } finally {
      setIsSyncing(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm animate-fadeIn">
      <div className="bg-[#1e293b] rounded-2xl shadow-2xl border border-slate-600 w-full max-w-md overflow-hidden">

        {/* Header */}
        <div className="bg-[#0f172a] p-6 border-b border-slate-700 flex justify-between items-center">
          <h3 className="text-xl font-bold text-white flex items-center gap-2">
            <Cloud className="text-cyan-400" /> {dict.title}
          </h3>
          <button onClick={onClose} className="text-slate-400 hover:text-white"><XCircle size={24}/></button>
        </div>

        {/* Content */}
        <div className="p-6 space-y-6">
          <p className="text-sm text-slate-400 leading-relaxed">{dict.desc}</p>

          {!isConnected ? (
            <div className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Project URL</label>
                <input 
                  value={url} 
                  onChange={(e) => setUrl(e.target.value)} 
                  placeholder={dict.urlPlaceholder}
                  className="w-full bg-[#0B1120] border border-slate-700 rounded-xl p-3 text-slate-200 focus:ring-1 focus:ring-cyan-500"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Anon Public Key</label>
                <input 
                  type="password"
                  value={key} 
                  onChange={(e) => setKey(e.target.value)} 
                  placeholder={dict.keyPlaceholder}
                  className="w-full bg-[#0B1120] border border-slate-700 rounded-xl p-3 text-slate-200 focus:ring-1 focus:ring-cyan-500"
                />
              </div>
              <button 
                onClick={handleConnect}
                className="w-full py-3 bg-cyan-600 hover:bg-cyan-500 text-white font-bold rounded-xl flex items-center justify-center gap-2 transition-all shadow-lg shadow-cyan-900/20"
              >
                <Link2 size={18} /> {dict.connect}
              </button>
            </div>
          ) : (
            <div className="space-y-4">
               <div className="bg-emerald-500/10 border border-emerald-500/30 p-4 rounded-xl flex items-center gap-3">
                 <CheckCircle className="text-emerald-400" size={24} />
                 <div>
                   <h4 className="font-bold text-emerald-200">{dict.status.connected}</h4>
                   <p className="text-xs text-emerald-400/70 truncate w-64">{url}</p>
                 </div>
               </div>

               <button 
                onClick={handleSync}
                disabled={isSyncing}
                className="w-full py-3 bg-slate-700 hover:bg-slate-600 text-white font-bold rounded-xl flex items-center justify-center gap-2 transition-all"
              >
                {isSyncing ? <Database className="animate-spin" /> : <UploadCloud size={18} />} 
                {dict.sync}
              </button>

               <button 
                onClick={handleDisconnect}
                className="w-full py-3 bg-red-900/20 hover:bg-red-900/40 text-red-400 border border-red-900/50 font-bold rounded-xl flex items-center justify-center gap-2 transition-all"
              >
                <LogOut size={18} /> {dict.disconnect}
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Plus, Search, LayoutGrid, Filter, BookOpen, ChevronRight, Home, Zap, Languages, X, Megaphone, Target, Lightbulb, BarChart2, Code, Shield, Download, UploadCloud, Database, Loader2, AlertTriangle, Cloud } from 'lucide-react';
import { PromptTable } from './components/PromptTable';
import { PromptForm } from './components/PromptModal';
import { AdminPanel } from './components/AdminPanel';
import { CloudModal } from './components/CloudModal';
import { PromptEntry, PromptFormData, Category } from './types';
import { TRANSLATIONS } from './constants';
import { storageService } from './services/storageService';

// Helper to get icon for category
const getCategoryIcon = (category: string) => {
  if (category === Category.Marketing) return <Megaphone size={16} className="text-pink-400" />;
  if (category === Category.Productivity) return <Target size={16} className="text-emerald-400" />;
  if (category === Category.Creativity) return <Lightbulb size={16} className="text-yellow-400" />;
  if (category === Category.Analysis) return <BarChart2 size={16} className="text-blue-400" />;
  if (category === Category.Development) return <Code size={16} className="text-cyan-400" />;
  return <LayoutGrid size={16} className="text-slate-400" />;
};

function App() {
  const [dbStatus, setDbStatus] = useState<'init' | 'loading' | 'ready' | 'error'>('init');
  const [prompts, setPrompts] = useState<PromptEntry[]>([]);
  const [isPersisted, setIsPersisted] = useState(false);
  const [isCloud, setIsCloud] = useState(false);
  const [showCloudModal, setShowCloudModal] = useState(false);

  const [view, setView] = useState<'list' | 'form' | 'admin'>('list');
  const [editingPrompt, setEditingPrompt] = useState<PromptEntry | undefined>(undefined);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('All');

  const searchInputRef = useRef<HTMLInputElement>(null);
  const categorySelectRef = useRef<HTMLSelectElement>(null);
  const importInputRef = useRef<HTMLInputElement>(null);

  const [lang, setLang] = useState<'es' | 'en'>('es');
  const t = TRANSLATIONS[lang];

  useEffect(() => {
    const initApp = async () => {
      setDbStatus('loading');
      const persisted = await storageService.init();
      setIsPersisted(persisted);
      setIsCloud(storageService.isCloudActive());
      try {
        const loadedPrompts = await storageService.loadPrompts();
        setPrompts(loadedPrompts);
        setDbStatus('ready'); 
      } catch (e) {
        console.error("Critical error loading DB:", e);
        setDbStatus('error');
      }
    };
    initApp();
  }, []);

  useEffect(() => {
    if (dbStatus === 'ready') {
      const saveToDb = async () => {
        try { await storageService.savePrompts(prompts); } 
        catch (e) { console.error("Autosave failed:", e); }
      };
      const timeoutId = setTimeout(saveToDb, 500);
      return () => clearTimeout(timeoutId);
    }
  }, [prompts, dbStatus]);

  const handleExportDB = () => {
    const dataStr = JSON.stringify(prompts, null, 2);
    const blob = new Blob([dataStr], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `promptlib_backup_${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImportClick = () => { importInputRef.current?.click(); };

  const handleFileImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!file.name.toLowerCase().endsWith('.json')) {
      alert(lang === 'es' ? "Error: Archivo no válido." : "Error: Invalid file.");
      e.target.value = ''; return;
    }
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (Array.isArray(json) && json.every(item => item.id && item.name)) {
             if(confirm(lang === 'es' ? "Reemplazar base de datos?" : "Replace DB?")) {
               setPrompts(json);
             }
        } else { alert("Formato inválido."); }
      } catch (err) { console.error(err); alert("Error JSON."); }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const filteredPrompts = useMemo(() => {
    return prompts.filter(p => {
      const matchesSearch = 
        p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.objective.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.recommendedAi.toLowerCase().includes(searchQuery.toLowerCase()) || 
        p.tags.some(t => t.toLowerCase().includes(searchQuery.toLowerCase()));
      const matchesCategory = selectedCategory === 'All' || p.category === selectedCategory;
      return matchesSearch && matchesCategory;
    });
  }, [prompts, searchQuery, selectedCategory]);

  const handleSave = (data: PromptFormData | PromptFormData[]) => {
    if (Array.isArray(data)) {
        const newPrompts: PromptEntry[] = data.map(item => ({
            ...item,
            id: Date.now().toString() + Math.random().toString(36).substr(2, 5)
        }));
        setPrompts(prev => [...newPrompts, ...prev]);
    } else {
        if (editingPrompt) {
          setPrompts(prev => prev.map(p => p.id === editingPrompt.id ? { ...data, id: p.id } : p));
        } else {
          const newPrompt: PromptEntry = { ...data, id: Date.now().toString() };
          setPrompts(prev => [newPrompt, ...prev]);
        }
    }
    setView('list');
    setEditingPrompt(undefined);
  };

  const handleDelete = (id: string) => {
    if (confirm(lang === 'es' ? '¿Eliminar?' : 'Delete?')) {
      setPrompts(prev => prev.filter(p => p.id !== id));
    }
  };

  const handleCreate = () => { setEditingPrompt(undefined); setView('form'); };
  const handleEdit = (prompt: PromptEntry) => { setEditingPrompt(prompt); setView('form'); };
  const handleCancel = () => { setView('list'); setEditingPrompt(undefined); };
  const toggleLanguage = () => { setLang(prev => prev === 'es' ? 'en' : 'es'); };
  const handleAdminClick = () => { setView('admin'); setEditingPrompt(undefined); }
  const handleTotalClick = () => { setSearchQuery(''); setSelectedCategory('All'); window.scrollTo({ top: 300, behavior: 'smooth' }); };
  const handleCategoryClick = () => { categorySelectRef.current?.focus(); categorySelectRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' }); };
  const handleModelClick = () => { searchInputRef.current?.focus(); searchInputRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' }); };

  const handleCloudConnect = async () => {
    setIsCloud(storageService.isCloudActive());
    // Refresh prompts from new source
    const loaded = await storageService.loadPrompts();
    setPrompts(loaded);
  };

  const stats = {
    total: prompts.length,
    categories: new Set(prompts.map(p => p.category)).size,
    models: new Set(prompts.map(p => p.recommendedAi)).size
  };

  if (dbStatus === 'error') {
    return (
      <div className="min-h-screen bg-[#0B1120] flex flex-col items-center justify-center text-red-500 gap-6 p-4 text-center">
        <div className="bg-red-900/20 p-6 rounded-full border border-red-500/30 animate-pulse"><AlertTriangle size={64} /></div>
        <h1 className="text-2xl font-bold">Error de Base de Datos</h1>
        <button onClick={() => window.location.reload()} className="px-6 py-3 bg-red-600 text-white rounded-xl font-bold">Recargar</button>
      </div>
    );
  }

  if (dbStatus === 'init' || dbStatus === 'loading') {
    return (
      <div className="min-h-screen bg-[#0B1120] flex flex-col items-center justify-center text-cyan-500 gap-4">
        <Loader2 size={48} className="animate-spin" />
        <span className="font-mono text-sm tracking-widest uppercase animate-pulse">Initializing...</span>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0B1120] font-sans text-slate-300 selection:bg-cyan-500/30 selection:text-cyan-200">
      <div className="bg-[#0f172a] border-b border-cyan-900/30 shadow-[0_4px_20px_-5px_rgba(6,182,212,0.1)] pb-24 relative overflow-hidden">
        <div className="absolute top-0 right-0 w-96 h-96 bg-purple-500/10 rounded-full blur-3xl pointer-events-none"></div>
        <div className="absolute top-0 left-0 w-96 h-96 bg-cyan-500/5 rounded-full blur-3xl pointer-events-none"></div>
        <header className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 relative z-10">
          <div className="flex justify-between items-center">
            <div className="flex flex-col gap-1">
              <div className="flex items-center gap-2 text-slate-400 text-xs font-mono mb-1 tracking-wider uppercase">
                <div className="flex items-center gap-1 cursor-pointer hover:text-cyan-400 transition-colors" onClick={() => setView('list')}>
                  <Home size={12} /><span>{t.app.home}</span>
                </div>
                {view === 'form' && (<><ChevronRight size={12} className="text-slate-600"/><span className="text-cyan-400 animate-pulse">{editingPrompt ? t.app.editPrompt : t.app.newPrompt}</span></>)}
                {view === 'admin' && (<><ChevronRight size={12} className="text-slate-600"/><span className="text-purple-400 animate-pulse">{t.app.admin}</span></>)}
              </div>
              <h1 className="text-3xl font-bold text-white tracking-tight flex items-center gap-3">
                <div className="relative"><BookOpen className="text-cyan-400" size={28} /><div className="absolute inset-0 bg-cyan-400 blur-md opacity-40"></div></div>
                <span className="bg-clip-text text-transparent bg-gradient-to-r from-white via-slate-200 to-slate-400">PromptLib <span className="text-cyan-500">Manager</span></span>
              </h1>
              <div className="flex items-center gap-2 mt-1 px-2 py-0.5 rounded-full bg-[#1e293b] border border-slate-700 w-fit cursor-pointer hover:bg-slate-800 transition-colors" onClick={() => setShowCloudModal(true)}>
                 {isCloud ? <Database size={10} className="text-purple-400" /> : <Database size={10} className="text-blue-400" />}
                 <span className={`text-[10px] font-mono tracking-tight ${isCloud ? 'text-purple-400' : 'text-blue-400'}`}>
                    {isCloud ? t.app.db.cloud : t.app.db.indexed}
                 </span>
              </div>
            </div>

            <div className="flex items-center gap-3">
              <button onClick={() => setShowCloudModal(true)} className={`flex items-center justify-center w-8 h-8 rounded-lg border ${isCloud ? 'border-purple-500 bg-purple-500/10 text-purple-400' : 'border-slate-700 bg-[#0B1120] text-slate-400'} hover:text-white`} title="Cloud Settings">
                  <Cloud size={14} />
              </button>

              <div className="hidden md:flex items-center gap-1 bg-[#1e293b] p-1 rounded-lg border border-slate-700 mr-2">
                 <button onClick={handleExportDB} className="p-2 text-slate-400 hover:text-cyan-400 hover:bg-cyan-950/30 rounded-md" title={t.app.backupDesc}><Download size={16} /></button>
